import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "synax-amshir-1",
    title: { en: "Amshir 1", ar: "1 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Ecumenical Council in Constantinople.", ar: "اجتماع المجمع المسكونى الثانى بالقسطنطينية سنة 381م" } },
      { kind: 'reading', text: { en: "On this day of the year 381 A.D., one hundred and fifty fathers assembled upon the order of Emperor Theodosius the Great, in the city of Constantinople. They assembled to judge Macedonius, Patriarch of Constantinople, and Sabellius and Apollinaris, for their blasphemy against God the Word and the Holy Spirit.", ar: "في مثل هذا اليوم من سنة 381 م اجتمع بمدينة القسطنطينية المئة والخمسون أبا بأمر الملك ثاؤدسيوس الكبير ، لمحاكمة مقدونيوس بطريرك القسطنطينية وسبيليوس وأبوليناريوس المجدفين علي الله الكلمة والروح القدس ، وذلك انه لما ذاع هذا التجديف خشي الأباء علي سلامة الكنيسة ، واعلموا الملك ثاؤدسيوس بهذه الهرطقات . فأمر بعقد مجمع وأرسل إلى كل من الأنبا تيموثاؤس بابا الإسكندرية الثاني والعشرين والأنبا داماسوس بابا رومية والأنبا بطرس بطريرك إنطاكية والأنبا كيرلس بطريرك أورشليم ، فحضروا ومعهم أساقفة كراسيهم ما عدا بابا رومية فانه لم يحضر بنفسه ولكنه أرسل نوابا عنه . ولما اجتمع المجمع المقدس بمدينة القسطنطينية دعوا مقدونيوس وسأله الأنبا تيموثاؤس بابا الإسكندرية ورئيس المجمع قائلا ما هو اعتقادك ؟ فأجاب إن الروح القدس مخلوق كسائر المخلوقات . فقال الأنبا تيموثاؤس إن الروح القدس هو روح الله . فإذا قلنا كزعمك إن روح الله مخلوق فنكون قد قلنا إن حياته مخلوقة ، فهو إذن عديم الحياة بدونها ، ثم نصحه إن يرجع عن سؤ رأيه . ولما رفض قطعه وجرده من رتبته ." } },
      { kind: 'reading', text: { en: "When this blasphemy became widespread, the fathers of the church were concerned about the peace of the church, and made these heresies known to Emperor Theodosius. He ordered that a council be assembled, and invited Abba Timothy, 22nd Pope of Alexandria; Abba Damasus, Pope of Rome; Abba Petros (Peter), Patriarch of Antioch; and Abba Cyril (Kyrillos), Patriarch of Jerusalem. They came to the council with their bishops, except the Pope of Rome, who delegated others to attend on his behalf.", ar: "ثم سال سبيليوس قائلا وأنت ما هو اعتقادك ؟ فأجاب إن للثالوث ذاتا واحدة وإقنوما واحدا . فقال له الأنبا تيموثاؤس إذا كان الثالوث كما زعمت ، فقد بطل ذكر الثالوث وبطلت أيضا معموديتك لأنها باسم الآب والابن والروح القدس ، ويكون الثالوث علي زعمك تألم ومات ، وبطل قول الإنجيل إن الابن كان قائما في الأردن ، والروح القدس نازلا عليه شبه حمامة ، والآب يناديه من السماء . ثم نصحه إن يرجع عن رأيه الفاسد فلم يقبل فقطعه وجرده من رتبته ." } },
      { kind: 'reading', text: { en: "When the holy council convened in Constantinople, they called upon Macedonius. Abba Timothy, Pope of Alexandria, who was presiding over the council, asked him, \"What is your belief?\" Macedonius answered that the Holy Spirit was created like any other creature. Abba Timothy said, \"The Holy Spirit is the Spirit of God. If we say as you claim that the Spirit of God is created, we are saying, in essence, that His Life is created, and therefore, He is 'lifeless' without it.\" He advised Macedonius to renounce his erroneous belief. When he refused, Macedonius was excommunicated, anathematized and striped of his rank.", ar: "ثم سال أبوليناريوس قائلا وأنت ما هو اعتقادك ؟ فأجاب إن تجسيد الابن كان باتحاده مع الجسد البشري وبدون النفس الناطقة ، لان لاهوته قام مقام النفس والعقل . فقال له الأنبا تيموثاؤس إن الله الكلمة قد اتحد بطبيعتنا لكي يخلصنا ، فان كان باتحاده بالجسد الحيواني فقط ، فهو إذن لم يخلص البشر ، بل الحيوانات ، لان البشر يقومون في يوم البعث بالنفس الناطقة العالقة ، التي معها يكون الخطاب والحساب ، وبها ينالون النعيم أو العذاب . وعلي ذلك قد بطلت منفعة التجسد . وإذا كان هكذا فكيف يقول عن ذاته عز وجل انه إنسان ، إذا كان لم يتحد بالنفس الناطقة العاقلة ؟ ثم نصحه ليرجع عن رأيه الفاسد فلم يقبل فقطعه أيضا كزميليه . أخيرا حرم المجمع الثلاثة ومن يقول بقولهم ، ثم كمل دستور الإيمان الذي وضعه أباء مجمع نيقية حتى قوله الذي ليس لملكه انقضاء ، وبالروح القدس . فزاد عليه أباء مجمع القسطنطينية ما يلي هذا القول إلى آخره وضعوا قوانين لا زالت في أيدي المؤمنين." } },
      { kind: 'reading', text: { en: "Then Abba Timothy asked Sabellius, \"And you, what is your belief?\" He answered, \"The Trinity is one being and one person.\" Abba Timothy said, \"If the Trinity is as you claim, then the mentioning of the Trinity is groundless, and your baptism is futile, because it is in the Name of the Father, the Son and the Holy Spirit, and the Trinity would have suffered pain and died, and the saying of the gospel would be invalid, when it is said that the Son was in the Jordan River, and the Holy Spirit descended upon Him in the likeness of a dove, and the Father called upon Him from heaven.\" Then Abba Timothy advised him to renounce his belief. When Sabellius did not accept, Abba Timothy excommunicated, anathematized and striped him of his rank.", ar: "صلاة هؤلاء الأباء القديسين تكون معنا آمين ." } },
      { kind: 'reading', text: { en: "Then Abba Timothy asked Apollinaris, \"And you, what is your belief?\" Apollinaris said, \"The Incarnation of the Son was by His union with the human flesh without the rational being, for His divinity replaced the soul and the mind of the human being.\" Abba Timothy replied, \"God the Word united with our nature to save us, therefore if He only united with the animal body, then He did not save mankind but the animals. Humans will rise on the day of Resurrection with the rational and speaking soul with which there will be the communication and the judgement, and with it they will be granted the blessing or the condemnation. Accordingly, the Incarnation would be in vain. If that was the case, why did He call Himself a man if He did not unite with the rational speaking soul?\" Then Abba Timothy advised him to turn away from his erroneous belief, but he also refused. He excommunicated Apollinaris as he did the other two friends.", ar: "" } },
      { kind: 'reading', text: { en: "Ultimately, the council excommunicated these three and all those who agreed with them. Then they completed the creed that was established by the fathers at the Council of Nicea until its saying, \"Of Whose Kingdom shall be no end.\" The fathers of the Council of Constantinople added, \"Truly we believe in the Holy Spirit, the Lord, Giver of Life... to the end.\" They put down many canons that are still in the hands of the believers today.", ar: "" } },
      { kind: 'reading', text: { en: "The prayers of these holy fathers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديس اباديون اسقف انصنا" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار استشهاد القديس اباديون أسقف انصنا . صلاته تكون معنا ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "The Commemoration of the Consecration of the Church of St. Peter, the Seal of Martyrs.", ar: "تكريس كنيسة القديس بطرس خاتم الشهداء بالاسكندرية" } },
      { kind: 'reading', text: { en: "On this day also, we celebrate the commemoration of the consecration of the Church of (1). He was martyred in Alexandria during the last days of the reign of Diocletian the Infidel.", ar: "في هذا اليوم نعيد بتذكار تكريس كنيسة القديس بطرس بابا الإسكندرية السابع عشر وخاتم الشهداء (الذي استشهد بالإسكندرية في أخر ملك دقلديانوس الشرير). وذلك انه لما تولي الملك البار قسطنطين الكبير ، وهدمت البرابي وبنيت الكنائس ، بني المؤمنين هذه الكنيسة غرب الإسكندرية علي اسم القديس بطرس خاتم الشهداء ، ولم تزل قائمة إلى ما بعد تملك العرب مصر حيث هدمت واندثرت ." } },
      { kind: 'reading', text: { en: "When Emperor Constantine the Great reigned, and all the idol temples were destroyed, churches were built. So the believers built this church west of Alexandria in the name of St. Peter, the Seal of Martyrs. The church existed till shortly after the reign of the Arabs over Egypt, when it was destroyed.", ar: "شفاعته تكون معنا . ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "His blessings be with us and glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-2",
    title: { en: "Amshir 2", ar: "2 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of the Great Saint Anba Paul, the First Hermit.", ar: "نياحة القديس أنبا بولا أول السياح" } },
      { kind: 'reading', text: { en: "On this day of the year 341 A.D., the great saint Anba Paul, the first hermit, departed. This Saint was from the city of Alexandria, and had a brother whose name was Peter.", ar: "في مثل هذا اليوم من سنة 341 م تنيح القديس العظيم الأنبا بولا أول السواح . كان هذا القديس من الإسكندرية ، وكان له أخ يسمي بطرس ، وبعد وفاة والدهما ، شرعا في قسمة الميراث بينهما ، فلما اخذ أخوه الجزء الأكبر تألم بولس من تصرف أخيه وقال له : لماذا لم تعطني حصتي من ميراث أبى ؟ فأجابه لأنك صبي واخشي إن تبدده ، أما انا فسأحفظه لك . وإذ لم يتفقا ، مضيا للحاكم ليفصل بينهما . وفيما هما ذاهبين ، وجدا جنازة سائرة في الطريق ، فسال بولس أحد المشيعين عن المتوفى ، فقيل له إنه من عظماء هذه المدينة وأغنيائها ، وهوذا قد ترك غناه وماله الكثير ، وها هم يمضون به إلى القبر بثوبه فقط . فتنهد القديس وقال في نفسه : ما لي إذن وأموال هذا العالم الفاني الذي سأتركه وأنا عريان . ثم التفت إلى أخيه وقال له : ارجع بنا يا أخي ، فلست مطالبا إياك بشيء مما لي . وفيما هما عائدين انفصل عنه بولس وسار في طريقه حتى وصل إلى خارج المدينة . فوجد قبرا أقام به ثلاثة ايام يصلي إلى السيد المسيح إن يرشده إلى ما يرضيه . أما أخوه فانه بحث عنه كثيرا ، وإذ لم يقف له علي اثر حزن حزنا عظيما وتأسف علي ما فرط منه ." } },
      { kind: 'reading', text: { en: "After the departure of their father, they divided the inheritance between them. When his brother took the greater share, Paul's feelings were hurt, by his brother's action. He said to his brother, \"Why don't you give me my rightful share of the inheritance of my father?\" Peter responded, \"You are a young man, and I am afraid that you might squander it. As for me, I will keep it for you.\"", ar: "أما القديس بولس فقد أرسل إليه الرب ملاكا أخرجه من ذلك المكان وسار معه إلى إن آتى إلى البرية الشرقية الداخلية ، وهناك أقام سبعين سنة لم يعاين أثناءها أحدا . وكان يلبس ثوبا من ليف ، وكان الرب يرسل إليه غرابا بنصف خبزة في كل يوم . ولما أراد الرب إظهار قداسته وبره ، أرسل ملاكه إلى الأب العظيم أنطونيوس ، الذي كان يظن انه أول من سكن البرية ، وقال له : يوجد في البرية الداخلية إنسان لا يستحق العالم وطأة قدميه ، وبصلاته ينزل الرب المطر والندي علي الأرض ، ويأتي بالنيل في حينه . فلما سمع أنطونيوس هذا قام لوقته وسار في البرية الداخلية مسافة يوم . فارشده الرب إلى مغارة القديس بولس فدخل إليه وسجد كل منهما للآخر وجلسا يتحدثان بعظائم الأمور . ولما صار المساء أتى الغراب ومعه خبزة كاملة . فقال القديس بولس للقديس أنطونيوس : الآن قد علمت انك من عبيد الله . إن لي اليوم سبعين سنة والرب يرسل لي نصف خبزة كل يوم ، أما اليوم فقد أرسل الرب لك طعامك ، والان أسرع واحضر لي الحلة التي أعطاها قسطنطين الملك لأثناسيوس البطريرك. فمضي إلى البابا أثناسيوس أخذها منه وعاد بها إليه . وفيما هو في الطريق رأي نفس القديس الأنبا بولا والملائكة صاعدين بها . ولما وصل إلى المغارة وجده قد تنيح ، فقبله باكيا ثم كفنه بالحلة واخذ الثوب الليف . ولما أراد مواراة جسده الطاهر تحير كيف يحفر القبر ، وإذا بأسدين يدخلان عليه وصارا يطأطأن بوجهيهما علي جسد القديس ، ويشيران برأسيهما كمن يستأذناه فيما يعملان . فعلم انهما مرسلان من قبل الرب ، فحدد لهما مقدار طول الجسد وعرضه فحفراه بمخالبهما . وحينئذ واري القديس أنطونيوس الجسد المقدس وعاد إلى الأب البطريرك واعلمه بذلك ، فأرسل رجالا ليحملوا الجسد إليه . فقضوا أياما كثيرة يبحثون في الجبل فلم يعرفوا له مكانا ، حتى ظهر القديس للبطريرك في الرؤيا واعلمه إن الرب لم يشأ إظهار جسده فلا تتعب الرجال ، فأرسل واستحضرهم ." } },
      { kind: 'reading', text: { en: "When they did not agree with each other, they went to the governor to judge between them. On their way, they saw a funeral procession. Paul asked one of the mourners about the deceased man. Paul was told that he was one of the noble and rich people of the city, and that he left his riches and his wealth behind, and that they were taking him to bury him with only his garment.", ar: "أما الثوب الليف فكان يلبسه الأب البطريرك ثلاث مرات في السنة أثناء التقديس . وفي أحد الأيام أراد إن يعرف الناس مقدار قداسة صاحبه فوضعه علي ميت فقام لوقته . وشاعت هذه الأعجوبة في كل ارض مصر والإسكندرية ." } },
      { kind: 'reading', text: { en: "St. Paul sighed in his heart and said to himself, \"What do I have to do then with all the money of this temporal world which I shall leave naked?\" He looked to his brother and said to him, \"My brother, let us return, for I shall not ask you for anything, not even for what is mine.\"", ar: "صلاته تكون معنا آمين." } },
      { kind: 'reading', text: { en: "On their way back, Paul left his brother and went on his way until he came out of the city. Paul found a grave where he stayed for three days praying to the Lord Christ to guide him to what pleases Him. As for his brother, he searched for Paul diligently and when he did not find him, he was very sorry for what he had done.", ar: "" } },
      { kind: 'reading', text: { en: "God sent St. Paul an angel who took him out of this place, and walked with him until they reached the eastern inner wilderness. He stayed there for 70 years, during which he saw no one. He put on a tunic made of palm tree fiber. The Lord sent him a raven every day with a half loaf of bread.", ar: "" } },
      { kind: 'reading', text: { en: "When the Lord wanted to reveal the holiness of St. Paul and his righteousness, He sent His angel to St. Antony (Antonius) the Great, who thought that he was the first to dwell in the wilderness. The angel told St. Antony, \"There is a man who lives in the inner wilderness; the world is not worthy of his footsteps. By his prayers, the Lord brings rain and dew to fall on the earth, and bring the flood of the Nile in its due season.\"", ar: "" } },
      { kind: 'reading', text: { en: "When St. Antony heard this, he rose right away and went to the inner wilderness, a distance of one day's walk. God guided him to the cave of St. Paul. He entered, and they bowed to each other, and sat down talking about the greatness of the Lord.", ar: "" } },
      { kind: 'reading', text: { en: "In the evening, the raven came bringing a whole loaf of bread. St. Paul said to St. Antony, \"Now, I know that you are one of the children of God. For 70 years, the Lord has been sending to me everyday, half a loaf of bread, but today, the Lord is sending your food also. Now, go and bring me back in a hurry the tunic that\nEmperor Constantine had given to Pope Athanasius.\"", ar: "" } },
      { kind: 'reading', text: { en: "St. Antony went to St. Athanasius, and brought the tunic from him and returned to St. Paul. On his way back, he saw the soul of St. Paul carried by the angels up to heaven. When he arrived to the cave, he found that St. Paul had departed from this world. He kissed him, weeping, and clothed him in the tunic that he asked for, and he took his fiber tunic.", ar: "" } },
      { kind: 'reading', text: { en: "When St. Antony wanted to bury St. Paul, he wondered how could he dig the grave? Two lions entered the cave, bowed their heads before the body of St. Paul, and shook their heads as if they were asking St. Anthony what to do. St. Antony knew that they were sent from God. He marked the length and width of the body on the ground, and they dug the grave with their claws, according to St. Antony's directions. St. Anthony then buried the holy body, and went back to Pope Athanasius and told him what had happened. St. Athanasius sent men to bring St. Paul's body to him. They spent several days searching in the mountains, but they could not find the place of his grave. St. Paul appeared to the Pope in a vision and told him that the Lord would not allow the revelation of the location of his body. He asked the Pope not to trouble the men, but to have them brought back.", ar: "" } },
      { kind: 'reading', text: { en: "Pope Athanasius used to put the palm fiber tunic on three times a year during the Divine Liturgy. One time, he wanted to let the people know about the holiness of the owner of that tunic. He put it over a dead man, and the dead man rose up instantly. The news of this miracle spread all around the land of Egypt.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Longinus, Abbot of El-Zugag Monastery.", ar: "نياحة القديس لونجينوس رئيس دير الزجاج" } },
      { kind: 'reading', text: { en: "On this day also, the pure saint Anba Longinus, the abbot of the El-Zugag monastery, departed. He was from Cilicia (in Asia Minor). He became a monk in one of the monasteries, where his father Lucianus became a monk after his wife had died.", ar: "في مثل هذا اليوم تنيح القديس الطاهر الأنبا لونجينوس رئيس دير الزجاج . وكان من أهل قيليقية . ترهب في أحد الأديرة التي كان قد ترهب فيها والده لوقيانوس بعد وفاة زوجته . وحصل بعد نياحة رئيس هذا الدير ، إن أراد الرهبان إقامة القديس لوقيانوس رئيسا عليهم فلم يقبل ، لأنه كان يبغض مجد العالم واخذ ابنه لونجينوس وآتى به إلي الشام وأقاما هناك في كنيسة . وقد اظهر الله فضائلهما بأجراء عدة آيات علي أيديهما ، وخوفا من مجد العالم ، استأذن لونجينوس أباه في الذهاب إلي مصر . ولما وصل قصد دير الزجاج غرب الإسكندرية ، فقبله الرهبان بفرح ، إلي إن تنيح رئيس الدير . ونظرا لما رأوه في القديس لونجينوس من الفضائل والسلوك الحسن فقد أقاموه رئيسا خلفه ، وبعد قليل أتى إليه أبوه لوقيانوس . وكانا يصنعان قلوع المراكب ويقتاتان من عملهما واجري الله علي أيديهما آيات كثيرة . ثم تنيح الأب لوقيانوس بسلام ولحقه ابنه بعد ذلك ." } },
      { kind: 'reading', text: { en: "When the abbot of this monastery departed, the monks wanted to appoint St. Lucianus an abbot over them, but he refused, for he shunned the vain glory of the world.", ar: "بركة صلاه هذين القديسين تكون معنا . ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "He took his son Longinus and went to Syria, where they lived in a church. God revealed their virtues by performing many miracles through them. For fear of the vain glory of this world, Longinus went to Egypt with his father's permission.", ar: "" } },
      { kind: 'reading', text: { en: "When he arrived, he went to the monastery of El-Zugag, west of Alexandria. The monks received him with joy. After the departure of the abbot, the monks appointed Anba Longinus abbot over them, for what they saw of his virtues and his good conduct. Shortly after, his father Lucianus came to him, and they worked together in making the canvas sails of boats, and sold them to support themselves. God performed many miracles and signs on their hands.", ar: "" } },
      { kind: 'reading', text: { en: "Father Lucianus departed from this world in peace, and shortly after, his son, Anba Longinus, departed also.", ar: "" } },
      { kind: 'reading', text: { en: "The prayers of these two saints be with us, and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-3",
    title: { en: "Amshir 3", ar: "3 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. James, the Ascetic.", ar: "نياحة القديس يعقوب الراهب" } },
      { kind: 'reading', text: { en: "On this day, St. James, the ascetic monk, departed. This father denounced the world since his childhood. He dwelt in a cave for 15 years, during which he struggled with long fasting and numerous prayers. He did not leave his cave all this time.", ar: "في مثل هذا اليوم تنيح الراهب الناسك القديس يعقوب . هذا الأب كان زاهدا في العالم منذ حداثته . فسكن إحدى المغائر وأقام بها خمس عشرة سنة . وقد اجهد نفسه في أثنائها بالأصوام الطويلة والصلوات المتواترة . ولم يخرج من مغارته طول هذه المدة . فتأمر عليه قوم من اتباع إبليس ، أوعزوا إلى زانية فتزينت وذهبت إليه ، ودخلت المغارة ، وتقدمت منه أخذت تداعبه حتى تستدرجه إلى الخطية ، ولكنه وعظها ، وذكرها بنار جهنم ، وبالعقوبات الدهرية ، فتابت علي يديه . وعادت إلى المدينة تردد الشكر لله ، الذي احسن إليها بالرجوع عن طريق الموت إلى الحياة ، وقد اجري الله علي يديه آيات كثيرة . ولما اكمل جهاده الحسن تنيح بسلام." } },
      { kind: 'reading', text: { en: "Some followers of the evil one plotted against him, and they sent him a harlot. She decorated herself and went and entered his cave. She tried to get closer to him and flirted with him to entice him to commit sin with her. But he preached to her, and reminded her of the fire of hell, and the eternal punishments. She repented on his hand and went back to the city, thanking God, Who had compassion on her and brought her back from the way of eternal death to the way of eternal life.", ar: "صلاته تكون معنا . ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "God performed many miracles through him. When he finished his good struggle in this life, he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us, and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نياحة القديس هدرا بحاجر بنهدب" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم تذكار نياحة القديس هدرا بحاجر بنهدب . صلاته تكون معنا و لربنا المجد دائما أبديا آمين" } }
    ],
  },
  {
    id: "synax-amshir-4",
    title: { en: "Amshir 4", ar: "4 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Agabus, One of the Seventy Disciples.", ar: "استشهاد القديس اغابوس احد السبعين رسولا" } },
      { kind: 'reading', text: { en: "On this day, St. Agabus, one of the seventy disciples, was martyred. The seventy disciples were chosen by the Lord to go before Him to preach the gospel. St. Agabus was with the twelve disciples in the upper room on the day of Pentecost, and he was filled with the Holy Spirit, the Comforter.", ar: "في مثل هذا اليوم استشهد القديس أغابوس أحد السبعين رسولا ، الذين اختارهم الرب ليكرزوا أمامه . وكان مع التلاميذ الاثني عشر في علية صهيون ، وامتلأ من مواهب الروح القدس المعزي ، ونال نعمة النبوة ، كما يخبرنا سفر أعمال الرسل بقوله &quot; وبينما نحن مقيمون أياما كثيرة انحدر من اليهودية نبي اسمه أغابوس. فجاء إلينا واخذ منطقة بولس وربط يدي نفسه ورجليه وقال : هذا يقوله الروح القدس &quot; الذي له هذه المنطقة هكذا سيربطه اليهود في أورشليم ويسلمونه إلى أيدي الأمم &quot; . وقد تمت هذه النبوة." } },
      { kind: 'reading', text: { en: "He received the gift of prophecy, as the Acts of the Apostles tells us, \"And as we stayed many days, a certain prophet named Agabus came down from Judea. When he had come to us, he took Paul's belt, bound his own hands and feet, and said, 'Thus says the Holy Spirit, so shall the Jews at Jerusalem bind the man who owns this belt, and deliver him into the hands of the Gentiles.'\" (Acts 21:10-11) This prophecy was fulfilled. (Acts 21:17-36)", ar: "و تنبأ أيضا عن حدوث جوع عظيم بالمسكونة كلها . وقد تم ذلك في ايام كلوديوس قيصر , ثم كرز ببشارة الإنجيل مع الرسل القديسين . وطاف بلادا كثيرة معلما وهاديا حتى رد كثيرين من اليهود واليونانيين إلى معرفة السيد المسيح وطهرهم بالمعمودية المحيية ، فقبض عليه اليهود بأورشليم وضربوه كثيرا ، ثم وضعوا في عنقه حبلا وجروه خارج المدينة حيث رجموه بالحجارة إلى إن اسلم روحه الطاهرة . عند ذلك نزل نور من السماء راه الجمع الحاضر كأنه عمود متصلا بجسده وبالسماء . أبصرت ذلك امرأة يهودية فقالت : حقا إن هذا الرجل بار ، وصاحت بأعلى صوتها قائلة : انا مسيحية مؤمنة باله هذا القديس ، فرجموها أيضا . وتنيحت ودفنت معه في مقبرة واحدة ." } },
      { kind: 'reading', text: { en: "He also prophesied about a famine on all the earth, and this was fulfilled during the time of Claudius Caesar, the Roman Emperor. (Acts 11:27-28)", ar: "صلاتهما تكون معنا . ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "He preached the gospel together with the holy apostles. He went to many countries, teaching and converting many of the Jews and the Greeks to the knowledge of the Lord Christ. He sanctified them by the life-giving baptism.", ar: "" } },
      { kind: 'reading', text: { en: "This moved the Jews of Jerusalem to arrest him, and they tortured him by beating him severely, and putting a rope around his neck, and they dragged him outside the city. They stoned him there until he gave up his pure spirit. At this moment, a light came down from heaven. Everyone saw it as a continuous column between his body and heaven. A Jewish woman saw it and said, \"Truly this man was righteous.\" She shouted in a loud voice, \"I am a Christian and I believe in the God of this saint.\" They stoned her also and she died and was buried with him in one tomb.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us and glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-5",
    title: { en: "Amshir 5", ar: "5 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Relocation of the Relics of the Forty-Nine Elders of the Wilderness of Shiheet (Scetis).", ar: "نقل اعضاء 49 شيوخ شيهيت" } },
      { kind: 'reading', text: { en: "Today also, we celebrate the commemoration of the relocation of the relics of the to their church in the monastery of St. Macarius(2).", ar: "في هذا اليوم نعيد بتذكار نقل أجساد الأباء الأطهار القديسين شيوخ برية شيهيت التسعة والأربعين إلى كنيستهم بدير القديس مقاريوس" } },
      { kind: 'reading', text: { en: "Their prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'reading', text: { en: "(2) The biography of the forty-nine martyrs is on the .", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Agrippinus, 10th Pope of Alexandria.", ar: "نياحة البابا اغربيينوس" } },
      { kind: 'reading', text: { en: "On this day of the year 181 A.D., the holy father Anba Agrippinus, 10th Pope of Alexandria, departed. This father was holy and pure and he feared God. He was ordained a priest on the church of Alexandria.", ar: "في مثل هذا اليوم من سنة 181 م تنيح الأب القديس الأنبا إغربينوس بابا الإسكندرية العاشر . كان هذا الأب قديسا طاهرا خائفا الله، فرسموه قسا علي كنيسة الإسكندرية . ولما تنيح الأب كلاديانوس البابا التاسع اختير هذا القديس من شعب المدينة الاكليروس بطريركا . فتولي بنعمة الله الخلافة علي الكرسي الرسولي ، وسار سيرا رسوليا ، وكرزا ومعلما الناس أصول الإيمان وشرائعه المحيية . مهتما بكل قواه في حراسة الرعية معلما ومصليا عن جميعهم . لم تقتن ذهبا ولا فضة ، إلا ما كان ضروريا لسد حاجته فقط . واكمل في الجهاد اثنتي عشرة سنة وتنيح بسلام . صلاته تكون معنا آمين." } },
      { kind: 'reading', text: { en: "When Pope Cladianus, 9th Pope departed, Anba Agrippinus was chosen Patriarch by the people and clergy of Alexandria. By the grace of God, he took over the apostolic throne of Alexandria and walked in the footsteps of the apostles.", ar: "" } },
      { kind: 'reading', text: { en: "Anba Agrippinus preached the word of God and taught the principle of faith with its life-giving laws. He Guarded his flock, with all his strength, by teaching them and praying on their behalf. He did not own any silver or gold, except for what met his basic personal needs. He completed his course after 12 years on the throne of St. Mark, and he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Saints Anba Bishay and Anba Abanoub.", ar: "نياحة القديس بيشاى صاحب الدير الاحمر" } },
      { kind: 'reading', text: { en: "On this day also, the church celebrates the commemoration of the saints Anba Bishay of Akhmim monastery, and Anba Abanub, known as the owner of the Golden Fan.", ar: "في هذا اليوم نعيد بتذكار القديسين الأنبا بيشاي صاحب دير أخميم و الأنبا ابانوب صاحب المروحة الذهب. صلاتهما تكون معنا آمين." } },
      { kind: 'reading', text: { en: "Their prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Apollo, friend of Anba Abib.", ar: "نياحة القديس ابللو رفيق القديس ابيب" } },
      { kind: 'reading', text: { en: "On this day also, the church commemorates the departure of St. Apollo, friend of (1).", ar: "في هذا اليوم تذكار نياحة القديس ابللو رفيق الانبا ابيب صلاته تكون معنا امين." } },
      { kind: 'reading', text: { en: "His prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نياحة القديس ابوليدس بابا روما" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تعيد الكنيسة بتذكار ظهور جسد القديس أبوليدس بابا رومية . كان هذا القديس رجلا فاضلا وكاملا في جيله ، فاختاروه لكرسي رومية بعد الأب اوجيوس . وكان ذلك في أول سنة من جلوس القديس الأنبا كلاديانوس البابا التاسع علي كرسي الإسكندرية. وكان مداوما علي تعليم شعبه وحراسته من الآراء الوثنية ، مثبتا إياهم علي الإيمان بالسيد المسيح ، فبلغ خبره مسامع الملك الكافر قلوديوس قيصر ، فقبض عليه وضربه ضربا مؤلما ، وأخيرا ربط في قدمه حجرا ثقيلا وطرحه في البحر في اليوم الخامس من أمشير. ولما كان الغد وجد أحد المؤمنين جسد القديس عائما علي وجه الماء ، والحجر مربوطا في قدمه . فأخذه إلى منزله وكفنه وذاع هذا الخبر في مدينة رومية وسائر البلاد التابعة لها ، حتى وصل إلى القيصر فطلب الجسد ولكن الرجل أخفاه ولم يظهره . ولهذا الأب تعاليم كثيرة بعضها عن الاعتقاد وعن التجسد وبعضها عظات لتقويم السيرة . ووضع أيضا ثمانية وثلاثين قانونا. صلاته تكون معنا آمين." } }
    ],
  },
  {
    id: "synax-amshir-6",
    title: { en: "Amshir 6", ar: "6 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of the Saints Abakir, John, the Three Virgins and Their Mother.", ar: "استشهاد القديسين اباكير ويوحنا والثلاثة عذارى وامهن" } },
      { kind: 'reading', text: { en: "On this day also, the saints Abakir; John; the three virgins, Theodora (which means the gift of God), Theopisti \"Theophana\" (which means the faithfulness of God), and Theodosia (which means the glory of God); and their mother, Athanasia (which means the immortal), were martyred.", ar: "في مثل هذا اليوم استشهد القديسون اباكير ويوحنا والثلاث عذارى، ثاؤذورا التي تفسيرها عطية الله ، وثاؤبستي التي تفسيرها أمانة الله ، وثاؤذكسيا التي تفسيرها مجد الله . وأمهن أثناسيا التي تفسيرها غير المائتة. وذلك إن القديس اباكير كان راهبا متعبدا منذ حداثته وكان القديس يوحنا جنديا من خاصة الملك . وقد تركا الإسكندرية وطنهما الأصلي وأقاما في إنطاكية . ولما أثار الملك دقلديانوس الاضطهاد علي المسيحيين ، اعترفا مع العذارى وأمهن أمامه بالسيد المسيح. وإذ عرف انهم من الإسكندرية أمر بإعادتهم إليها . فلما وصلوا إلى هناك قدموهم إلى الوالي فاعترفوا بالسيد المسيح فأمر بقطع رؤوسهم . وكانت القديسة أثناسيا تثبت بناتها وتصبرهن وتعرفهن بانهن اذا استشهدن يصرن عرائس المسيح . وهكذا قطعوا رؤوسهن اولا ثم امهن فالقديسين اباكير ويوحنا . وبعد ذلك طرحوا أجسادهم للوحوش وطيور السماء . ولكن بعض المؤمنين أتوا واخذوا الأجساد ليلا ووضعوها في تابوت ." } },
      { kind: 'reading', text: { en: "St. Abakir was a monk since his young age, and St. John was a soldier in the private guards of the Emperor. They left Alexandria, their own home town, and lived in Antioch. When Diocletian incited the persecution against the Christians, they confessed their faith in the Lord Christ along with the virgins and their mother.", ar: "صلاتهم تكون معنا ولربنا المجد دائما أبديا آمين." } },
      { kind: 'reading', text: { en: "When the Emperor knew that they were from Alexandria, he returned them to the governor of Alexandria. When they came to Alexandria, and were brought before the Governor, they confessed their faith in the Lord Christ. He ordered them beheaded. St. Athanasia was comforting and confirming her daughters and telling them that if they were martyred, they would become the brides of Christ. The virgins were beheaded first, then their mother, then St. Abakir and St. John.", ar: "" } },
      { kind: 'reading', text: { en: "Their bodies were cast to the wild beasts and to the birds of the sky. However, some believers came and took their bodies by night and they placed them in a coffin and hid them until the end of the time of persecution.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us, and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نياحة البابا مرقس الرابع" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار نياحة البابا مرقس الرابع (84) . صلاته تكون معنا ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "", ar: "نياحة القديس زانوفيوس" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار نياحة القديس زانوفيوس . صلاته تكون معنا ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "The Appearance of the Body of St. Apolidus (Hippolytus), Pope of Rome.", ar: "" } },
      { kind: 'reading', text: { en: "On this day the church celebrates the appearance of the body of St. Apolidus (Hippolytus), Pope of Rome. He was a virtuous and a perfect man in his generation.", ar: "" } },
      { kind: 'reading', text: { en: "He was chosen to the Roman See after Father Augius. This was in the first year of the enthronement of Abba Cladianus, 9th Pope of Alexandria. Pope Apolidus was always teaching his people and guarding them from the pagan influences, confirming them in the faith of the Lord Christ.", ar: "" } },
      { kind: 'reading', text: { en: "When reports of St. Apolidus reached the infidel Emperor Claudius Caesar, he arrested him and tortured him severely. The Emperor then tied his feet with a heavy stone, and cast him in the sea on the .", ar: "" } },
      { kind: 'reading', text: { en: "On the following day, one of the faithful found the body of the saint floating above the water, and the stone was bound to his feet. The man took it to his home and shrouded the body. The news spread in the City of Rome and in all the neighboring cities, and it reached Caesar, who asked for the body, but the man hid it.", ar: "" } },
      { kind: 'reading', text: { en: "This father left a great wealth of teachings about the Incarnation, and several sermons about Christian teaching. He also established 38 bylaws.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us all. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-7",
    title: { en: "Amshir 7", ar: "7 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "نياحة البابا الكسندروس 43" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم من سنة 715 م تنيح الأب القديس ألكسندروس الثاني بابا الإسكندرية الثالث والأربعين . كان هذا القديس من أهل بنا . وترهب بدير الباتيرون أي دير الأباء . وهو الذي كان معروفا بدير الزجاج الكائن غرب الإسكندرية. ونظرا لتقواه وعلمه اختير لكرسي البطريركية . وقد نالته في مدة رئاسته شدائد كثيرة . وكان معاصرا للخليفة الوليد بن عبد الملك الذي لما تولي الخلافة عين أخاه عبد الله واليا علي مصر سنة 698 م فأساء عبد الله معاملة المسيحيين . وصادر رهبان برية شيهيت وبلغ به شره انه دخل يوما ديرا قبلي مصر حيث ابصر أيقونة العذراء مريم والدة الإله . ولما سال عنها وقيل له إنها صورة العذراء مريم أم المسيح مخلص العالم . بصق علي الصورة قائلا: إن عشت فسأبيد النصارى ثم جدف علي السيد المسيح أيضا. فلما صار الليل رأى في نومه ما أزعجه وادخل الرجفة إلى قلبه , فكتب يخبر أخاه قائلا إنني تألمت البارحة إذ رأبت رجلا جالسا علي منبر عظيم ووجهه يشرق اكثر من الشمس , وحوله ربوات حاملين سلاحا , وكنت انا وأنت مربوطين ومطروحين خلفه فلما سالت من هذا ؟ قيل لي هذا يسوع المسيح ملك النصارى الذي هزات به بالأمس . ثم أتاني واحد من حاملي السلاح فطعنني بحربة في جنبي . فحزن أخوه جدا من تلك الرؤيا . أما عبد الله هذا فانه أصيب بحمي شديدة ومات في تلك الليلة . وبعد أربعين يوما مات أخوه الوليد أيضا." } },
      { kind: 'reading', text: { en: "", ar: "و في سنة 701 م تولي أخر مكانه وحذا حذوه فأساء إلى المسيحيين وقبض علي القديس ألكسندروس وظل يعذبه إلى إن جمع له من المؤمنين ثلاثة آلاف دينار فأهلكه الله سريعا. وقام بعده وال آخر اشر منه فقبض وزيره علي الأب البطريرك وطلب منه ثلاثة آلاف دينار. فاعتذر إليه الأب قائلا إن المال الذي قدمه لسلفه ، جمع بعضه من المؤمنين والبعض الآخر استدانه فلم يقبل الوالي منه هذا القول وأخيرا طلب الأب منه مهلة فأمهله ، فمضي إلى الصعيد لجمعها من صدقات المؤمنين وفي أثناء تجوله حدث إن راهبا سائحا أمر اثنين من تلاميذه الرهبان بحفر مغارة وفيما كانا يحفران وجدا خمسة أكواب من نحاس مملوءة ذهبا . فاحتفظا بواحد منها واعطبا السائح الأربعة . فأرسلها هذا إلى الأب البطريرك , أما التلميذان فأخذا الذهب ومضيا إلى العالم وتركا الرهبنة وتزوجا واقتنيا الجواري والعبيد والمواشي . وعلم بهما الوالي فاستدعاهما إليه وهددهما فاخبراه بأمر الخمسة الأكواب وإن أربعة منها أخذها الأب البطريرك , فأسرع توا إلى الدار البطريركية ونهب ما وجده من أواني الكنائس ثم قبض علي الأب البطريرك أهانه وأودعه السجن . وطالبه بالأكواب وبالثلاثة آلاف دينار ولم يطلقه حتى دفعها." } },
      { kind: 'reading', text: { en: "", ar: "و بعد ذلك بقليل مات هذا الوالي وقام بعده وال آخر اشر منه إذ انه كلف المؤمنين إن يرسموا علي أيديهم عوض علامة الصليب المجيد . اسم الوحش الذي تنبأ عنه يوحنا الثاؤلوغوس أمر إن يكون هذا في سائر البلاد . وطلب من الأب البطريرك إن يرسم هو أيضا علي يده هذه العلامة فأبى ، وإذ أصر رجاه الأب إن يمهله ثلاثة ايام ثم مضي إلى قلايته وسال الرب يسوع إن لا يتخلي عنه حتى لا يقع في هذه التجربة . فسمع الرب صلاته وافتقده بمرض بسيط فذهب واستأذن الوالي في الذهاب إلى الإسكندرية فلم يسمح له ، ظنا منه انه إنما يتمارض ليعفي من الوشم . وبعد ذلك ألهمه الرب انه بعد أربعة ايام يتنيح فابلغ ذلك إلى تلاميذه وطلب منهم أعداد مركبة لحمل جسده ودفنه جوار أجساد الأباء القديسين. ثم تنيح بسلام فحملوا جسده ونقلوه كما طلب." } },
      { kind: 'reading', text: { en: "", ar: "و في زمن هذا الأب كان للملكية بمصر بطريرك يسمي أنسطاسيوس وقد أثار عليه غضب شعبه لمسالمته للأرثوذكسيين ومحبته لهم , فتركهم وجاء إلى البابا ألكسندروس واعترف أمامه بالإيمان الأرثوذكسي فأكرمه البابا ألكسندروس إكراما كثيرا وأراد إن يسلم إليه شئون البطريركية وينفرد هو للعبادة في أحد الأديرة , فأبى الأب أنسطاسيوس وقال له لو كنت ارغب في البطريركية لبقيت هناك فقد كنت بطريركا ولكني أريد إن اكون لك تلميذا . وأخيرا قبل إن يتسلم إحدى الاسقفيات فرعي الرعية التي أؤتمن عليها احسن رعاية. وقد أقام الأب ألكسندروس علي الكرسي البطريركي 24 سنة و9 اشهر . صلاته تكون معنا آمين ." } },
      { kind: 'heading', text: { en: "", ar: "نياحة البابا ثيؤدوروس 45" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم من سنة 728 م تنيح الأب القديس ثاؤذورس بابا الإسكندرية الخامس والأربعون وكان هذا الأب راهبا بدير عند مريوط يعرف بدير طنبورة تحت إرشاد وتدبير شيخ فاضل قديس يدعي يوأنس. وقد أوحى إليه من الروح القدس إن تلميذه تادرس سيصير يوما ما بطريركا. فاخبر من يهمهم الأمر ومن يلوذون به بهذا. وكان تادرس مجاهدا في عبادته كاملا في إتضاعه ووداعته . فاختير بإرادة الله للبطريركية فرعي رعية السيد المسيح افضل رعاية . وكان مداوما علي القراءة ووعظ شعبه في اغلب الأيام خصوصا ايام الآحاد والأعياد . واكمل علي الكرسي المرقسي اثنتي عشرة سنة وتنيح بسلام . صلاته تكون معنا . ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Fabianus (Fabrianus), Pope of Rome.", ar: "" } },
      { kind: 'reading', text: { en: "On this day, St. Fabianus, Pope of Rome, was martyred. This father was a righteous scholar. He was ordained Pope for the city of Rome, so he taught his people and guided them in the way of Christian perfection.", ar: "" } },
      { kind: 'reading', text: { en: "Decius, the head of the army, killed Emperor Philip, and replaced him as emperor. Decius incited a severe persecution against the Christians, and many were martyred. This infidel built a huge temple in the middle of the city of Ephesus, and erected in it idols, where he offered sacrifices to them. He then ordered to behead everyone who refused to sacrifice to these gods.", ar: "" } },
      { kind: 'reading', text: { en: "When Decius knew that St. Fabianus was against the worship of idols and that he was teaching the faithful to be steadfast in their faith, he brought him to Ephesus. Decius commanded St. Fabianus to sacrifice to the idols. St. Fabianus did not yield to him and ridiculed his idols. The Emperor punished him with many tortures for a long time and at the end, he beheaded him with the sword. St. Fabianus thus received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "This pope stayed on the throne for 12 years, the major part of which was tranquil and peaceful.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-8",
    title: { en: "Amshir 8", ar: "8 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Feast of Presenting the Lord Christ in the Temple.", ar: "دخول السيد المسيح الى الهيكل سن اربعين يوما" } },
      { kind: 'reading', text: { en: "On this day we celebrate the feast of presenting the Lord Christ to the temple after 40 days of His blessed birth. St. Joseph the righteous and His mother, the Virgin Mary, presented Him in the temple, to fulfill the Mosaic Law.", ar: "في هذا اليوم نعيد بتذكار دخول السيد المسيح إلى الهيكل. بعد أربعين يوما من ميلاده المجيد ، حيث قدمه يوسف الصديق والعذراء والدته ، ليكملا ما فرضته الشريعة الموسوية علي شعب إسرائيل . ويقول لوقا البشير انه عندما قدمه أبواه ليصنعا له حسب عادة الناموس ، أخذه سمعان الشيخ علي ذراعيه وبارك الله قائلا &quot; الآن تطلق عبدك يا سيد حسب قولك بسلام &quot;." } },
      { kind: 'reading', text: { en: "says that when His parents brought Him according to the custom of the law, the just and devout Simeon the elder took Him in his arms and blessed God and said, \"Lord, now You are letting Your servant depart in peace, according to Your Word; for my eyes have seen Your salvation which You have prepared before the face of all people, a light to bring revelation to the Gentiles, and the Glory of Your people Israel.\" (Luke 2:29-32)", ar: "أما سمعان هذا فهو أحد السبعين شيخا الذين ترجموا التوراة من العبرانية إلى اليونانية . وذلك انه لما ملك بطليموس الملقب بالغالب حوالي سنة 269 قبل الميلاد . أرسل بتدبير من الله إلى أورشليم ، واستحضر سبعين رجلا من أحبار اليهود وعلمائهم ، وأمرهم إن يترجموا له التوراة من العبرانية إلى اليونانية ثم عزل كل اثنين منهم في مكان خاص لكي لا يتفقوا علي ترجمة واحدة ، وليضمن نسخة صحيحة بعد مقارنة هذه الترجمات . وكان سمعان الشيخ من بينهم وحدث انه لما وصل إلى ترجمة قول اشعياء النبي &quot; هو ذا العذراء تحبل وتلد ابنا &quot; خشي إن يكتب &quot; عذراء تحبل &quot; فيهزا به الملك فأراد إن يكتب كلمة &quot; فتاة &quot; عوض كلمة عذراء ولما تألم في داخله لهذه الترجمة غير الصحيحة ، أعلن له الله في رؤيا انه لا يري الموت قبل إن يري مسيح الرب المولود من العذراء . وقد تم ذلك وعاش هذا البار نحو ثلاثمائة سنة حيث ولد السد المسيح . وكان بصره قد كف فلما حمل الصبي علي ذراعيه ابصر واعلمه الروح القدس إن هذا هو الذي كنت تنتظره &quot; فبارك الله وقال الآن تطلق عبدك يا سيد حسب قولك بسلام . لان عيني قد أبصرتا خلاصك . الذي أعددته قدام وجه جميع الشعوب . نور إعلان للأمم ومجدا لشعبك إسرائيل &quot; ." } },
      { kind: 'reading', text: { en: "Simeon was one of the 70 elders who translated the Old Testament from Hebrew to Greek. This was in the time of Ptolemy Soter in the year 296 B.C., who was sent by the will of God to Jerusalem. He brought 70 men from among the learned Jewish teachers and scholars and commanded them to translate the Old Testament from Hebrew to Greek(1).", ar: "بركة صلاة هذا البار تكون معنا ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "He put every two of them in an isolated place so they would not agree on one translation, and to ensure a correct text after comparing all of the translations. Simeon the elder was one of them. When Simeon was translating the verse from 7:14, \"Behold, the virgin shall conceive and bear a Son, and shall call His name Immanuel,\" he was afraid to translate that a virgin would conceive, because the King would mock him. He wanted to translate the virgin as a \"young lady.\"", ar: "ملحوظة علي طقس اليوم :" } },
      { kind: 'reading', text: { en: "He was disturbed because of this inaccurate translation, and God revealed to him in a vision that he would not die before he would see Christ the Lord born of a virgin.", ar: "+ إذا وقع العيد في صوم نينوي أو في الصوم الكبير أو يوم أحد تقرأ فصول العيد." } },
      { kind: 'reading', text: { en: "This was fulfilled and he lived about three hundred years. When Christ was born; he was very well advanced in age and his sight dimmed.", ar: "+ تعمل الدورة بعد إنجيل القداس ويلف الإنجيل بستر حرير ابيض ويزف 3 مرات في الهيكل ." } },
      { kind: 'reading', text: { en: "When he carried the child Jesus in his hands, his sight came back to him, and the Holy Spirit told him, \"This is the child that you have been waiting for.\" He blessed God and said, \"You are letting Your servant depart in peace according to Your Word, for my eyes have seen Your salvation which You have prepared before the face of all peoples, a light to bring revelation to the Gentiles and the Glory of Your people Israel.\" (Luke 2:28-32)", ar: "" } },
      { kind: 'reading', text: { en: "The prayers of this righteous man be with us, and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نياحة القديس سمعان الشيخ" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار نياحة القديس سمعان الشيخ . صلاته تكون معنا ولربنا المجد دائما أبديا آمين ." } }
    ],
  },
  {
    id: "synax-amshir-9",
    title: { en: "Amshir 9", ar: "9 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "نياحة القديس برسوما أب رهبان السريان" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم من سنة 458 م تنيح الأب المغبوط الأنبا برسوما أب رهبان السريان . وكان أبوه من ساموساط ، وتنبأ عنه رجل قديس قبل ولادته قائلا لوالديه سيخرج منكما ثمر صالح وينتشر ذكره في الأرض . وقد تم هذا القول إذ انه عندما شب برسوما قليلا ترك أبويه وقصد نهر الفرات حيث أقام زمانا عند رجل قديس يدعي إبراهيم . وبعد ذلك انفرد في الجبل , فاجتمع حوله تلاميذ كثيرون . وكان يصوم أسبوعا أسبوعا . وقد اجري الله علي يديه أيات كثيرة . وحدث في بعض الأيام غلاء في تلك البلاد ، فعرفه الرب بصلاته . وكان معاصرا للقديس سمعان العمودي ، الذي لما علم به زاره وتبارك الاثنان من بعضهما . وقد اشتهر بمقاومته لشيعة نسطوريوس . وشهد مجمع أفسس بدعوة من الملك ثاؤدسيوس الصغير الذي أكرمه كثيرا ، بعد إن يسعى به البعض إليه بأنه يعيش ببذخ ، وإذ استدعاه ورأي صلاحه ة تقشفه ، وكذب المتقولين عليه ، أعاده إلى ديره بالإكرام والإجلال . ولما جمع مرقيان الملك المجمع الخلقدوني ، طلب الأباء من الملك إلا يدعي برسوما إلى المجمع لعلمهم بالنعمة التي فيه . ولما قرر المجمع القول بالطبيعيتين ، قاوم القديس برسوما هذه التعاليم الباطلة فنالته شدائد كثيرة من شيعة الخلقيدونيين . وبعد ذلك لما أراد الرب إن ينقله من هذا العالم أرسل إليه ملاكه يعرفه انه لم يبق له إلا أربعة ايام ، فأوصى تلاميذه إن يذهبوا إلى بعض البلاد المجاورة ، ويثبتوا أهلها علي الإيمان الأرثوذكسي ، ثم باركهم وتنيح بسلام . وقد ظهر وقت نياحته عمود نور قائم علي باب قلايته ، أبصره المؤمنون من بعد ، فأتوا ووجدوه قد تنيح ، فتباركوا منه ودفنوه بإكرام . صلاته تكون معنا آمين ." } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديس بولس السريانى" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهد القديس بولس السرياني ، الذي ولد بمدينة الإسكندرية من أبوين سرياني الجنس ، ثم شكنا في مدينة الاشمونين ، واقتنيا أموالا كثيرة عن طريق التجارة ، وسمع القديس بولس بتعذيب الولاة للمسيحيين . فلما توفي أبواه . وزع الأموال علي المساكين وصلي إلى الله إن يهديه إلى الطريق الذي يرضيه . فأرسل له ملاكه سوريئيل وقال له : قد رسم لي الرب إن اكون معك وأقويك فلا تخف . فقام وأتى إلى والي انصنا واعترف أمامه بالسيد المسيح ، فأمر بان يعري من ثيابه . ويضرب بالسياط ، ثم توضع مشاعل في جنبيه . فلم يخف . ثم حاول إغراءه بالمال فقال له : قد ترك لي أبواي كثيرا من الذهب والفضة فلم التفت إليها حبا في الرب يسوع المسيح ، فكيف انظر إلى مالك الآن ؟ فغضب الوالي وعذبه بكل أنواع العذاب . فجاء إليه الملاك سوريئيل وشفاه وعزاه وقواه . وبعد ذلك أمر الوالي إن يطلقوا عليه حيات سامة فلم تؤذه . ولما مضي الوالي إلى الإسكندرية ، آخذه معه إلى هناك وأودعه في السجن ، حيث التقي بصديقيه القديسين الأنبا إيسى وتكله أخته ، فصافحهما وابتهجت أرواحها . وأوحى إليه الرب انه سيستشهد في هذه المدينة . ولما عزم الوالي علي العودة أمر فقطعوا راس القديس بولس علي شاطئ البحر . فأتى قوم من المؤمنين واخذوا جسده وكفنوه وحفظوه عندهم . صلاته تكون معنا ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديس سمعان" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار استشهاد القديس سمعان . صلاته تكون معنا ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "The Departure of St. Severus, Patriarch of Antioch.", ar: "" } },
      { kind: 'reading', text: { en: "On this day of the year 538 A.D., the holy father St. Severus, Patriarch of Antioch, departed. He was from Asia Minor. His grandfather, whose name was also Severus, saw in a vision someone telling him, \"The child who is for your son will strengthen Orthodoxy, and his name will be after your name.\" When his son had this saint, he called him Severus. He was taught the Greek wisdom and church subjects.", ar: "" } },
      { kind: 'reading', text: { en: "Once, the saint was strolling outside the city, a shut-in saint came out of his cave crying, \"Welcome to you Severus, teacher of Orthodoxy, and Patriarch of Antioch.\" Severus marvelled at how he called him by his name, for he did not know him before, and how he foretold what would become of him.", ar: "" } },
      { kind: 'reading', text: { en: "Severus grew in virtue and became a monk in the monastery of St. Romanus. The fame of his righteousness and his ascetic life spread out. When the Patriarch of Antioch departed, the bishops had a consensus to ordain him the Patriarch of the city in the year 512 A.D. The church was illuminated by his teachings which spread to all the universe, and he was one of the fathers who attended the Universal Council at Ephesus.", ar: "" } },
      { kind: 'reading', text: { en: "Shortly after, Emperor Anastasius died and Justinian, who was Chalcedonian in faith, reigned after him. He called upon this holy father and gave him great honors to persuade him to change his stand and to follow the Emperor's belief, but the Saint refused. The Emperor became angry, but the Saint did not fear his anger, and so the Emperor ordered him to be killed. Theodora, the Emperor's wife who was Orthodox in faith, knew about what the Emperor intended to do, so she told the saint to flee from his face.", ar: "" } },
      { kind: 'reading', text: { en: "St. Severus escaped to the land of Egypt and traveled everywhere and visited monasteries disguised as a monk. He strengthened the faith of the believers in the Orthodox doctrine. He dwelt in the city of Sakha in the home of a holy lay leader called Doretheos. God performed through him many miracles. He departed in the city of Sakha, and his body was relocated to the monastery of El-Zugag.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. James (Yacobus), 50th Pope of Alexandria.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also of the year 821 A.D., the great saint Abba James (St. Yacobus), 50th Pope of Alexandria, departed. He was a monk in the monastery of St. Macarius. For his holiness and righteousness, he was chosen by a consensus to become patriarch after Pope Mark, 49th Pope, had departed. He was enthroned in the month of Bashans in the year 810 A.D.", ar: "" } },
      { kind: 'reading', text: { en: "St. James renovated the churches and populated the monasteries, and God granted him the gift of performing miracles. One of the deacons in Alexandria dared to say to him rudely, \"Pay what you owe to the churches, or else go to your monastery.\" The Pope replied to him, \"You will never see me again from now on.\" The deacon went home, immediately became sick and died shortly after.", ar: "" } },
      { kind: 'reading', text: { en: "Another miracle: There was a lay leader (Archon) named Macarius from Nabarouh who was very well advanced in years and had no children. After a while, God gave him a son. He made a feast to celebrate this occasion, and invited Abba James. During the celebration, the child died but his father did not panic. He carried the child in his hands and placed him in faith before the Pope, trusting that God would hear His chosen one, and give life to his child. The Pope took the child and made the sign of the cross on his forehead, his heart and his chest, while he prayed, \"My Master, Jesus Christ, the Giver of Life, raise this child alive again by Your mighty power.\" He breathed in his face, and the soul of the child returned to him, and he gave him to his father. When he finished his good strife, Abba James departed in peace, after he had been on the throne of St. Mark for 10 years, 9 months and 28 days.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us, and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-10",
    title: { en: "Amshir 10", ar: "10 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. James the Apostle, Son of Alphaeus.", ar: "استشهاد القديس يعقوب الرسول" } },
      { kind: 'reading', text: { en: "On this day, St. James the Apostle, son of Alphaeus, was martyred. After he had preached the Gospel in many cities, he returned to Jerusalem and entered the temple of the Jews. He preached the gospel publicly and proclaimed the faith of the Lord Christ and His resurrection.", ar: "في مثل هذا اليوم استشهد القديس يعقوب الرسول ابن حلفا . وذلك انه بعدما نادي بالبشري في بلاد كثيرة عاد إلى أورشليم ، ودخل هيكل اليهود ، وكرز بالإنجيل جهارا ، وبالإيمان بالسيد المسيح وقيامة الأموات . فاختطفه اليهود وأتوا به إلى اكلوديوس نائب ملك رومية وقالوا له إن هذا يبشر بملك أخر غير قيصر ، فأمر إن يرجم بالحجارة فرجموه حتى تنيح بسلام فاخذ قوم من المؤمنين جسده ودفنوه بجانب الهيكل. صلاته تكون معنا آمين." } },
      { kind: 'reading', text: { en: "The Jews abducted him and brought him to Claudius, the deputy of the Roman emperor, and told him that he was preaching another king instead of Caesar. Claudius ordered him to be stoned to death, until he departed in peace. The faithful took his body and buried him beside the temple.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Philo, Bishop of the Persian.", ar: "استشهاد القديس فيلو أسقف فارس" } },
      { kind: 'reading', text: { en: "Today also, the honorable St. Philo, bishop of the Persians, was martyred by the hand of the Persian emperor. When he did not accept worshipping fire and the sun, they tortured him with different kinds of tortures, and then they beheaded him with the sword.", ar: "في هذا اليوم تذكار القديس الجليل فيلو أسقف فارس ، الذي استشهد علي يد ملك الفرس لأنه لم يقبل إن يعبد النار أو يسجد للشمس . فعذبوه بكل أنواع العذاب وأخيرا قطعوا رأسه بحد السيف . صلاته تكون معنا ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Justus, Son of Emperor Numerian.", ar: "استشهاد القديس يسطس بن نوماريوس" } },
      { kind: 'reading', text: { en: "On this day also, St. Justus, son of Emperor Numerian, was martyred. When he returned from war, he found that Emperor Diocletian had married his sister and had become the new emperor. Emperor Diocletian had apostatized the faith in the Lord Christ, and St. Justus was greatly sorrowful for what happened.", ar: "في مثل هذا اليوم استشهد القديس يسطس ابن الملك نورماريوس . وذلك انه لما عاد من الحرب ، وجد إن دقلديانوس قد تزوج أخته وصار ملكا ، وانه قد ارتد عن الإيمان بالسيد المسيح فعز عليه ذلك كثيرا. ولما اجتمع وجوه المملكة وأكابرها لتجلسه ملكا عوض أبيه ، لم يقبل مفضلا المملكة السمائية علي الأرضية. وتقدم إلى دقلديانوس واعترف أمامه باسم المسيح فأرسله هو أبالي ابنه وثاؤكليا زوجته إلى والي الإسكندرية ، وأمره إن يلاطفهم أولا ، وإن لم يذعنوا يقطعوا رؤوسهم . فلما وصلوا الإسكندرية ومعهم بعض من غلمانهم ، قابلهم الوالي بلطف ، وإذ لم يستطع تحويلهم عن الإيمان بالمسيح له المجد أرسل يسطس إلى انصنا ، أبالي إلى بسطة . وثاؤكليا زوجته إلى صا . وقد اخذ كل منهم غلاما معه ، حتى إذا اكمل جهاده يهتم بجسده . فعذبوهم وقطعوا رؤوسهم فنالوا إكليل الشهادة . صلاتهم تكون معنا آمين." } },
      { kind: 'reading', text: { en: "When the nobles of the empire met together to enthrone him in place of his father, he did not accept, for he preferred the heavenly kingdom over the earthly. He came before Diocletian and declared his faith in the Lord Christ. The Emperor sent St. Justus with his son Abali and his wife Theoclea to the Governor of Alexandria, and commanded him to persuade them first and to behead them if they did not obey.", ar: "" } },
      { kind: 'reading', text: { en: "When they arrived in Alexandria, the Governor received them and treated them well to persuade them. As he could not change their deep conviction in their faith in the Lord Christ, to Whom is the Glory, he sent St. Justus to Antinoe (Ansena), Abali, his son, to Basta (near Zagazig, Sharkia), and Theoclea to Sa (Salhagar, Gharbia). Each of them took a servant with him so when they completed their strife, the servant would take care of the body. They tortured them, beheaded them, and they received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Isidore of Pelusium.", ar: "استشهاد القديس ايسيذورس الفرمى" } },
      { kind: 'reading', text: { en: "On this day also, the ascetic, scholar and holy man, Anba Isidore of Pelusium (El-Pharma), departed. His parents were among the rich and noble people of Egypt. He was related to Pope Cyril and , patriarchs of Alexandria.", ar: "في مثل هذا اليوم تنيح القديس الناسك العالم الأنبا ايسيذوروس الفرمي . كان أبواه من أغنياء مصر ووجوهها ، وكان قريبا للقديسين ثاؤفيلس وكيرلس باباوي الإسكندرية ، ولم يكن له اخوة سواه ، فأدباه بكل أدب وعلماه كتب الكنيسة . ثم تعلم اللغة اليونانية وأتقنها وبرع فيها حتى فاق كثيرين . وكان مع ذلك ناسكا متواضعا . ولما علم إن أهل البلاد والأساقفة عازمين عل تقدمته بطريركا علي الكرسي المرقسي ، هرب ليلا إلى جبل الفرما وترهب في دير هناك ، ثم انتقل منه إلى مغارة صغيرة ، أقام بها وحده عدة سنوات . وقد وضع في أثنائها عدة كتب أكثرها عن الملوك والرؤساء, وشرح كتبا كثيرة من العهدين القديم والجديد . وقد وجد في بعض كتب السير إن عدد الرسائل التي أرسلها إلى البطاركة والأساقفة وغيرهم يبلغ ثماني عشرة آلف رسالة . وكانت مواهب الروح القدس تتدفق عليه . ولما وصل إلى شيخوخة صالحة مرضية انتقل إلى الرب صلاته تكون معنا آمين ." } },
      { kind: 'reading', text: { en: "He was the only child of his parents, who cared about his education. They taught him the books of the church, and the Greek language in which he excelled and surpassed many. He was also ascetic and humble. When he knew that the people of Alexandria and the bishops wanted to make him the Patriarch of Alexandria, he took flight by night to Pelusium and became a monk in a monastery there.", ar: "" } },
      { kind: 'reading', text: { en: "Then he went to a small cave where he lived alone for several years. During these years, he wrote many books about emperors and governors. He also commented on many books of the Old and New Testaments of the Bible. His epistles that he sent to bishops and patriarchs were counted as eighteen thousand epistles. The gifts of the Holy Spirit poured upon him, and he reached a good old age, then departed to the Lord in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نوة الشمس الصغرى شمالية غربية ممطرة 3 ايام" } },
      { kind: 'reading', text: { en: "", ar: "في اشهر الشتاء تتعرض الأجزاء المطلة علي البحر المتوسط لظاهرة تولد الانخفاضات الجوية الإعصارية التي تميز الأحوال المناخية في إقليم البحر المتوسط وتعرف في الإسكندرية باسم النوات." } },
      { kind: 'reading', text: { en: "", ar: "هي اضطرابات جوية تنشأ عنها دوامة هوائية دائرية أو بيضاوية ذات ضغط منخفض وسط مساحة ضغطها مرتفع وتندفع فيها الرياح علي شكل حلزوني نحو مركز منخفض بحيث يكون سيرها ضد اتجاه عقارب الساعة ." } }
    ],
  },
  {
    id: "synax-amshir-11",
    title: { en: "Amshir 11", ar: "11 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "نياحة البابا يوأنس الثالث عشر ال94" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار نياحة البابا يؤنس الثالث عشر ال94 . صلاته تكون معنا و لربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Fabianus (Fabrianus), Pope of Rome.", ar: "استشهاد القديس فابيانوس بابا روما" } },
      { kind: 'reading', text: { en: "On this day, St. Fabianus, Pope of Rome, was martyred. This father was a righteous scholar. He was ordained Pope for the city of Rome, so he taught his people and guided them in the way of Christian perfection.", ar: "في مثل هذا اليوم استشهد القديس فابيانوس بابا رومية ، وكان هذا الأب عالما صالحا مجاهدا . فقدم بطريركا علي مدينة رومية ، فاخذ يعلم شعبه ويقوده في طريق الكمال. وحدث إن داكيوس القائد قام علي فيلبس الملك وقتله وجلس مكانه ، وأثار علي المؤمنين اضطهادا شديدا ، واستشهد علي يديه كثيرون. وقد شيد هذا الكافر هيكلا عظيما وسط مدينة أفسس وأقام فيه أصناما كان يقدم لها الذبائح . ثم أمر بقتل من لا يذبح لها . فلما بلغه إن القديس فابيانوس يعطل عبادة الأصنام بتعاليمه للمؤمنين وتثبيتهم علي الإيمان ، استحضره بأفسس وطلب منه إن يقدم الذبيحة للأصنام فلم يقبل بل سخر بأصنامه . فعاقبه بعقوبات شديدة مدة كاملة ، وأخيرا قتله بالسيف فنال إكليل الشهادة . وقد أقام هذا البابا علي الكرسي اثنتي عشرة سنة قضي شطرا كبيرا منها في هدوء وإطمئنان . صلاته تكون معنا . ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "Decius, the head of the army, killed Emperor Philip, and replaced him as emperor. Decius incited a severe persecution against the Christians, and many were martyred. This infidel built a huge temple in the middle of the city of Ephesus, and erected in it idols, where he offered sacrifices to them. He then ordered to behead everyone who refused to sacrifice to these gods.", ar: "" } },
      { kind: 'reading', text: { en: "When Decius knew that St. Fabianus was against the worship of idols and that he was teaching the faithful to be steadfast in their faith, he brought him to Ephesus. Decius commanded St. Fabianus to sacrifice to the idols. St. Fabianus did not yield to him and ridiculed his idols. The Emperor punished him with many tortures for a long time and at the end, he beheaded him with the sword. St. Fabianus thus received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "This pope stayed on the throne for 12 years, the major part of which was tranquil and peaceful.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-12",
    title: { en: "Amshir 12", ar: "12 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Archangel Michael.", ar: "التذكار الشهري لرئيس الملائكة الجليل ميخائيل" } },
      { kind: 'reading', text: { en: "On this day we celebrate, commemorating the honorable , the intercessor of mankind.", ar: "فى مثل هذا اليوم تحتفل الكنيسة بتذكار رئيس جند السماء الملاك الجليل ميخائيل الشفيع فى جنس البشر. شفاعته تكون معنا . آمين." } },
      { kind: 'reading', text: { en: "His intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Gelasius.", ar: "جلاسيوس الناسك" } },
      { kind: 'reading', text: { en: "Also on this day, St. Gelasius, the struggling ascetic, departed. He was born of Christian parents, who brought him up in the Christian faith. They taught him the church subjects, and then he was ordained a deacon in the church. He labored in his obedience to Christ and in carrying His yoke.", ar: "في مثل هذا اليوم تنيح الأب الناسك المجاهد القديس جلاسيوس ، وقد ولد من أبوين مسيحيين ، فربياه تربية مسيحية ، وعلماه علوم الكنيسة ، ثم قدماه شماسا . فاجهد نفسه في طاعة المسيح وحمل نيره ، وذهب فترهب في برية شيهيت . وبعد زمن رسم قسا فأرشده ملاك الرب إلى مكان بعيد وهناك جمع حوله جماعة من الرهبان ، فكان لهم خير مثال ، وكان يعد نفسه كواحد منهم . وقد تناهي في الصبر وطول الاناة ، حتى أمكنه نسخ الكتاب المقدس ، ووضعه في الكنيسة ليقرا فيه من يشاء من الرهبان . وحدث إن زاره مرة رجل غريب وسرق هذا الكتاب وعرضه للبيع فاشتراه أحد الأشخاص ، وأراد إن يعرف قيمته فذهب به إلى القديس جلاسيوس وأراه إياه فعرف انه كتابه . فقال له بكم باعك صاحبه ؟ فقال بستة عشرة دينارا . فقال له انه رخيص فاشتراه وعاد به إلى منزله . ولما جاء البائع لأخذ ثمنه قال له : أنني عرضته علي الأب جلاسيوس فقال إن الثمن كثير . فقال له : أما قال لك شيئا أخر . فقال لا فقال : إنني لا أريد بيعه . ثم اخذ الكتاب وتوجه به إلى الأب جلاسيوس وقدمه له باكيا نادما علي فعله فلم يقبله منه ، وبعد إلحاح شديد ودموع كثيرة ، قبل إن يسترده . وقد منحه الله نعمة عمل المعجزات ، منها انه اهدي إلى الدير في أحد الأيام مقدارا من السمك . وبعد طهيه وضعه الطباخ في المطبخ ووكل بحراسته أحد الغلمان وهذا أكل منه جزءا كبيرا . فلما عرف الطباخ ذلك غضب علي غلامه لآته أكل منه قبل وقت الأكل وقبل إن يباركه الشيوخ ، وضربه ضربة أصابت منه مقتلا ، فذعر الطباخ وذهب إلى القديس جلاسيوس واخبره بما جري منه ، فقال له خذه وضعه بالكنيسة أمام الهيكل واتركه . ثم جاء الشيخ والرهبان إلى الكنيسة وصلوا صلاة الغروب ، وبعد ذلك خرج الشيخ من الكنيسة فقام الغلام وتبعه ، ولم يعلم أحد من الرهبان بهذا إلا بعد نياحته . ولما اكمل هذا الأب حياته بشيخوخة صالحة أراد الرب إن يريحه من أتعاب هذا العالم فتنيح تاركا هذا التذكار الحسن. صلاته تكون معنا ولربنا المجد دائما أبديا آمين." } },
      { kind: 'reading', text: { en: "He went to the wilderness of Shiheet and became a monk. Afterwards, he was ordained a priest, and the angel of the Lord guided him to a distant place where many monks gathered around him, and he was a great example for them. He considered himself as one of them. He was patient and long suffering to the point that he transcribed the Holy Bible and placed it in the church for the other monks to read.", ar: "" } },
      { kind: 'reading', text: { en: "One day a stranger visited him and stole the transcribed Bible and went to try to sell it to someone. That person wanted to know its value, so he went to St. Gelasius and showed him the Bible. St. Gelasius knew that it was his book and asked him, \"For how much did he sell it to you?\" He answered, \"For sixteen Dinari.\" The saint said to him that it was cheap, and so the man took it and went to his home.", ar: "" } },
      { kind: 'reading', text: { en: "When the seller came back to him to pick up the price, he said to him, \"I have shown the Bible to Father Gelasius and he said that the price was too high.\" The seller asked, \"Did the father tell you anything else?\" The buyer replied, \"No.\" The man who stole the Bible said, \"I do not want to sell it.\" He took the book and went to Father Gelasius and gave it to him weeping and regretting what he did. The saint did not accept it from him. However, after the man had insisted with many tears, the saint at last accepted it from him.", ar: "" } },
      { kind: 'reading', text: { en: "God granted this saint the gift of performing miracles. One day, the monastery was presented with an amount of fish. After they were cooked, the cook asked one of the servants to guard it, but the servant ate a great part of it. When the cook knew what had happened, he was angry at that servant, for he ate before the time of eating and before the elders had blessed it. The cook beat him with a deadly hit that killed him.", ar: "" } },
      { kind: 'reading', text: { en: "The cook was afraid of what he had done and went to St. Gelasius and told him what had happened. The saint told him to take the body and put it in the church in front of the altar and to leave it there. The saint and the monks came to the church, prayed the Vespers prayer, and then the saint departed from the church, and the boy rose up and followed him. The monks did not know of this miracle until the saint had departed.", ar: "" } },
      { kind: 'reading', text: { en: "When this father finished the course of his life in a good old age, the Lord wanted him to rest from the labors of this world, and he departed leaving us with this good memory.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-13",
    title: { en: "Amshir 13", ar: "13 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Sergius of Atripe, His Father, Mother, Sister, and Many Others with Them.", ar: "استشهاد القديس سرجيوس الاتربى وابية وامة وكثيرين معه." } },
      { kind: 'reading', text: { en: "On this day, St. Sergius, his father, his mother, his sister and many others with them, were martyred. This saint was born in the city of Atripe to a righteous father whose name was Theodore, and a faithful mother whose name was Mary.", ar: "في هذا اليوم تذكار استشهاد القديس سرجيوس الأتربي وأبية وأمة وكثيرين معه. . صلاتهم تكون معنا و لربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "When he was 20 years old, St. Sergius desired to die for the Name of the Lord Christ. He presented himself to Cyprianus (Cyprian), the governor, and confessed his faith in the Lord Christ. The governor commanded him to be tortured with different kinds of tortures and to cast him in prison.", ar: "" } },
      { kind: 'reading', text: { en: "At night he saw in a vision as if he was in heaven, and he saw the mansions of the saints. His soul was greatly comforted, and the Lord Christ healed him from his afflictions.", ar: "" } },
      { kind: 'reading', text: { en: "A priest by the name of Mansoon heard about the labors of St. Sergius. Fr. Mansoon came with two deacons to Atripe and confessed the Name of the Lord Christ before the governor. The governor beat them with great cruelty. A multitude of people watched the tortures, and moved with compassion toward the priest, who could not do anything but to look at them, preach and command them to be steadfast in their faith in the Lord Christ. He prayed and blessed them and they all confessed the Orthodox faith. After they had been tortured, they were all beheaded, and received the crown of life. However, the Governor tortured the priest with fire, but the Lord saved him. The Governor sent him to Alexandria where he received his crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "As for St. Sergius, Governor Cyprianus brought him and tortured him with excruciating tortures but the Lord healed, strengthened and comforted him. They brought an idol and ordered him to worship it. He kicked the idol with his foot and it fell and broke. Cyprianus believed instantly and said, \"The god that cannot save itself, cannot save others.\" The captain of the soldiers \"Ohios\" continued to torture St. Sergius, and ordered to skin him and to rub his wounds with salt and vinegar, but the Lord gave him strength and grace.", ar: "" } },
      { kind: 'reading', text: { en: "His mother and his sister came to visit him and saw him in this condition, they wept bitterly, until his sister died from her extreme grief, but God raised her up by the prayers of the saint.", ar: "" } },
      { kind: 'reading', text: { en: "came, wrote the biography of St. Sergius, and promised him that he would take care of his body and his burial. The captain \"Ohios\" ordered that St. Sergius be tortured by pressing his body through the pressing wheel (Hinbazeen), that his nails be pulled out, that he be placed over an iron bed, with a fire under it, and that torches of fire be placed in his ears. The Lord strengthened him through all of this and healed him. When \"Ohios\" the captain was tired of torturing him, he decided to behead him.", ar: "" } },
      { kind: 'reading', text: { en: "St. Sergius called his mother and sister to bid them farewell. They came with the rest of his family and when they saw him tied up with the bridle of a horse that was dragging him to the place of his martyrdom, they protested to the Governor for his extreme cruelty. He ordered to behead them all and they all received the crown of life and the eternal bliss.", ar: "" } },
      { kind: 'reading', text: { en: "There was a young boy among the crowd whose eyes were opened by the Lord and he saw the souls of the saints who were martyred carried by the angels, ascending to heaven. He cried with a loud voice saying, \"O My Lord Jesus Christ, have mercy upon me.\" His parents were afraid that the governor would hear him and destroy them because of him. When they could not calm him down, they put their hands upon his mouth to prevent him from screaming, asking the help of the Lord Christ, until he gave up his pure soul at the hand of the Lord.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Timothy III, 32nd Pope of Alexandria.", ar: "نياحة البابا تيموثاوس الثالث بابا الاسكندرية الثاني و الثلاثون" } },
      { kind: 'reading', text: { en: "On this day also of the year 528 A.D., the holy father Abba Timothy III, 32nd Pope of Alexandria, departed. His enthronement on the apostolic throne was in 511 A.D. He suffered many hardships because he was steadfast in the Orthodox faith.", ar: "في مثل هذا اليوم من سنة 528 م تنيح الاب القديس الانبا تيموثاوس الثالث بابا الاسكندرية الثاني و الثلاثون و كان جلوسه علي الكرسي الرسولي سنة 511 م و قد نالت هذا الاب شدائد كثيرة بسبب المحافظة علي الايمان المستقيم. و حضر في ايامه القديس ساويرس بطريرك انطاكية الي الديار المصرية هربا من الاضطهاد . و تجول الاثنان في البلاد و الاديرة يثبتان الشعب علي المعتقد الارثوذكسي و لانه لم يوافق الملك مرقيان علي قوانين المجمع الخليقدوني فقد نفاه عن كرسيه و في يوم نفيه عارض المؤمنين في تنفيذ الامر فقتل منهم بامر الملك نحو مئتي الف نفس . و قد تنيح هذا الاب في المنفي هو و القديس ساويرس الانطاكي بعد إن اقام علي الكرسي المرقسي 17 سنة صلاته تكون معنا . و لربنا المجد دائما ابديا امين ." } },
      { kind: 'reading', text: { en: "In his days, St. Severus, Patriarch of Antioch, came to Egypt escaping persecution. The two saints traveled together to Egyptian cities and monasteries confirming the people in the Orthodox faith.", ar: "" } },
      { kind: 'reading', text: { en: "Because he did not agree with Emperor Marcion with regard to the canons of the Council of Chalcedon, he was exiled.", ar: "" } },
      { kind: 'reading', text: { en: "On the day of his exile, the faithful opposed the enforcement of the order of his exile, and many of them were killed, about two hundred thousand, by the order of the Emperor. The saint departed in exile together with St. Severus of Antioch, after he had been on the apostolic throne for 17 years.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-14",
    title: { en: "Amshir 14", ar: "14 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Severus, Patriarch of Antioch.", ar: "نياحة القديس ساويرس بطريرك انطاكية" } },
      { kind: 'reading', text: { en: "On this day of the year 538 A.D., the holy father St. Severus, Patriarch of Antioch, departed. He was from Asia Minor. His grandfather, whose name was also Severus, saw in a vision someone telling him, \"The child who is for your son will strengthen Orthodoxy, and his name will be after your name.\" When his son had this saint, he called him Severus. He was taught the Greek wisdom and church subjects.", ar: "في مثل هذا اليوم من سنة 538 م تنيح الأب القديس ساويرس بطريرك إنطاكية الذي كان من أسيا الصغرى وكان جده يسمي ساويرس وقد رأي في رؤيا من يقول له : إن الولد الذي لابنك سيثبت الأرثوذكسية ، ويدعي اسمه علي اسمك ولما رزق ابنه هذا القديس اسماه ساويرس فتعلم الحكمة اليونانية ثم العلوم الكنسية وفيما هو سائر خارج المدينة إذ بقديس حبيس يخرج من مغارته ويصيح به قائلا : مرحبا بك يا ساويرس معلم الأرثوذكسية وبطريرك إنطاكية . فتعجب ساويرس كيف يدعوه باسمه وهو لم يعرفه ، وكيف علم بما سيكون منه . وقد نما ساويرس في الفضيلة وترهب بدير القديس رومانوس وذراع بره ونسكه . فلما تنيح بطريرك إنطاكية اتفق رأي الأساقفة علي تقدمه بطريركا علي المدينة وذلك سنة 512 م فاستضاءت الكنيسة بتعاليمه التي ذاعت في المسكونة كلها كما كان من الأباء الذين حضروا مجمع أفسس ولم يلبث قليلا حتى مات الملك أنسطاسيوس وملك بعده يوسطينيانوس وكان علي عقيدة مجمع خلقيدونية . فاستدعي هذا الأب وأكرمه كثيرا عساه يذعن لرأيه فلم يقبل . فغضب عليه غضبا شديدا ولكنه لم يخش غضب الملك فأمر بقتله . وعلمت بذلك تاؤدورة زوجة الملك وكانت أرثوذكسية المعتقد فأشارت علي القديس إن يهرب من وجهه . فخرج سرا وجاء إلى ارض مصر وطاف البلاد والأديرة في زي راهب وكان يثبت المؤمنين علي الأيمان المستقيم ، وأقام في مدينة سخا عند أرخن قديس يسمي دوروثاؤس وقد اجري الله علي يديه أيات كثيرة وتنيح بمدينة سخا ونقل جسده إلى دير الزجاج. صلاته تكون معنا آمين." } },
      { kind: 'reading', text: { en: "Once, the saint was strolling outside the city, a shut-in saint came out of his cave crying, \"Welcome to you Severus, teacher of Orthodoxy, and Patriarch of Antioch.\" Severus marvelled at how he called him by his name, for he did not know him before, and how he foretold what would become of him.", ar: "" } },
      { kind: 'reading', text: { en: "Severus grew in virtue and became a monk in the monastery of St. Romanus. The fame of his righteousness and his ascetic life spread out. When the Patriarch of Antioch departed, the bishops had a consensus to ordain him the Patriarch of the city in the year 512 A.D. The church was illuminated by his teachings which spread to all the universe, and he was one of the fathers who attended the Universal Council at Ephesus.", ar: "" } },
      { kind: 'reading', text: { en: "Shortly after, Emperor Anastasius died and Justinian, who was Chalcedonian in faith, reigned after him. He called upon this holy father and gave him great honors to persuade him to change his stand and to follow the Emperor's belief, but the Saint refused. The Emperor became angry, but the Saint did not fear his anger, and so the Emperor ordered him to be killed. Theodora, the Emperor's wife who was Orthodox in faith, knew about what the Emperor intended to do, so she told the saint to flee from his face.", ar: "" } },
      { kind: 'reading', text: { en: "St. Severus escaped to the land of Egypt and traveled everywhere and visited monasteries disguised as a monk. He strengthened the faith of the believers in the Orthodox doctrine. He dwelt in the city of Sakha in the home of a holy lay leader called Doretheos. God performed through him many miracles. He departed in the city of Sakha, and his body was relocated to the monastery of El-Zugag.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. James (Yacobus), 50th Pope of Alexandria.", ar: "نياحة القديس الأنبا يعقوب بابا الإسكندرية الخمسون" } },
      { kind: 'reading', text: { en: "On this day also of the year 821 A.D., the great saint Abba James (St. Yacobus), 50th Pope of Alexandria, departed. He was a monk in the monastery of St. Macarius. For his holiness and righteousness, he was chosen by a consensus to become patriarch after Pope Mark, 49th Pope, had departed. He was enthroned in the month of Bashans in the year 810 A.D.", ar: "في مثل هذا اليوم من سنة 821 م تنيح القديس العظيم الأنبا يعقوب بابا الإسكندرية الخمسون . كان هذا الأب راهبا بدير القديس مقاريوس ونظرا قداسته وتقواه اجمع الكل علي انتخابه بطريركا بعد نياحة البابا مرقس التاسع والأربعين وجلس علي الكرسي في شهر بشنس سنة 810م فجدد الكنائس وعمر الأديرة وقد وهبه الله عمل الآيات . من ذلك إن شماسا بالإسكندرية تجرا عليه بوقاحة قائلا ادفع ما عليك للكنائس أو امض إلى ديرك فأجابه البابا قائلا انك لا تعود تراني منذ الآن فمضي الشماس إلى بيته ومرض لوقته ومات بعد حين ، ومنها أيضا إن أرخنا اسمه مقاريوس من نبروه كان قد طعن في السن ولم يرزق نسلا ، وبعد زمن رزقه الله ولدا فأقام وليمة دعا إليها هذا القديس وحدث أثناء الوليمة إن مات الطفل فلم يضطرب والده ، بل حمله بإيمان ووضعه أمام البابا واثقا إن الله يسمع لصفيه ويعيد نفس الطفل إليه فاخذ البابا الطفل ورشمه بعلامة الصليب علي جبهته وصدره وقلبه ، وهو يصلي قائلا : يا سيدي يسوع المسيح الواهب الحياة . أقم بقدرتك هذا الطفل حيا لأبيه ثم نفخ في وجهه فعادت نفس الطفل إليه ودفعه إلى أبيه . ولما اكمل جهاده الحسن تنيح بسلام بعد إن أقام علي الكرسي المرقسي عشر سنين وتسعة اشهر وثمانية وعشرون يوما . صلاته تكون معنا . ولربنا المجد دائما أبديا آمين." } },
      { kind: 'reading', text: { en: "St. James renovated the churches and populated the monasteries, and God granted him the gift of performing miracles. One of the deacons in Alexandria dared to say to him rudely, \"Pay what you owe to the churches, or else go to your monastery.\" The Pope replied to him, \"You will never see me again from now on.\" The deacon went home, immediately became sick and died shortly after.", ar: "" } },
      { kind: 'reading', text: { en: "Another miracle: There was a lay leader (Archon) named Macarius from Nabarouh who was very well advanced in years and had no children. After a while, God gave him a son. He made a feast to celebrate this occasion, and invited Abba James. During the celebration, the child died but his father did not panic. He carried the child in his hands and placed him in faith before the Pope, trusting that God would hear His chosen one, and give life to his child. The Pope took the child and made the sign of the cross on his forehead, his heart and his chest, while he prayed, \"My Master, Jesus Christ, the Giver of Life, raise this child alive again by Your mighty power.\" He breathed in his face, and the soul of the child returned to him, and he gave him to his father. When he finished his good strife, Abba James departed in peace, after he had been on the throne of St. Mark for 10 years, 9 months and 28 days.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us, and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-15",
    title: { en: "Amshir 15", ar: "15 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Paphnoute (Paphnotius).", ar: "نياحة القديس بفنوتيوس الراهب" } },
      { kind: 'reading', text: { en: "On this day also, the ascetic St. Paphnoute (Paphnotius) departed. He became a monk at a young age, and followed the hardest way in his monastic life.", ar: "في مثل هذا اليوم تنيح القديس الناسك العابد الأنبا بفنوتيوس وقد ترهب هذا الأب منذ حداثته وسلك اشق طرق النسك ثم ألهمه الله إن يتجول في البرية الداخلية . وهناك رأي كثيرين من القديسين السواح المجاهدين فاستطلع أخبارهم ودونها . ومن هؤلاء القديس تيموثاوس والقديس أبو نفر السائحين . وقد نال في أول تجوله شدائد كثيرة من جوع وعطش ولكن ملاك الرب كان يظهر له ويقويه ولما اكمل جهاده تنيح بسلام ." } },
      { kind: 'reading', text: { en: "God inspired him to travel to the inner wilderness, and there he saw many hermits and anchorites and St. Paphnoute wrote about them. Among those was St. Timothy and St. Abu Nofr. In his travels, he suffered much hunger and thirst, but the angel of the Lord appeared to him often to strengthen him. When he finished his strife, he departed in peace.", ar: "صلاته تكون معنا . ولربنا المجد دائما أبديا آمين ." } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Consecration of the First Church Dedicated for the Forty Martyrs of Sebaste.", ar: "تذكار تكريس كنيسة الاربعين شهيدا الذين استشهدوا في سبسطية" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the consecration of the church of the forty martyrs from Sebaste by the hand of Emperor Licinius(1). It was the first church that was built after their names. St. Basil the Great consecrated it, wrote their biographies and established a great feast day for them.", ar: "في هذا اليوم تذكار تكريس كنيسة الاربعين شهيدا الذين استشهدوا في سبسطية علي يد ليكينيوس قيصر ، وهي أول كنيسة بنيت علي اسمهم وكرسها القديس باسيليوس الكبير وهو الذي كتب تاريخهم وثبت لهم عيدا عظيما . شفاعتهم تكون معنا امين ." } },
      { kind: 'reading', text: { en: "Their intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Zechariah, the Prophet.", ar: "نياحة القديس زكريا النبي ابن براشيا احد الاثني عشر" } },
      { kind: 'reading', text: { en: "On this day St. Zechariah the Prophet, the son of Berechiah, one of the twelve minor prophets, departed. He was from the tribe of Levi, born in the land of Gilead, and was exiled to the land of the Chaldeans.", ar: "في مثل هذا اليوم تنيح القديس زكريا النبي ابن براشيا أحد الاثني عشر نبيا وهو من سبط لاوي . ولد في ارض جلعاد وسبي إلى ارض الكلدانيين . وهناك أبتدأ نبوته في السنة الثانية لملك داريوس وهي سنة 520 ق.م. فتنبأ عن يهوشع بن يهو صاداق وزربابل من شالتئيل ، بأنهم يبنيان الهيكل وتنبأ ايضا عن دخول الرب أورشليم راكبا علي حمار وعلي جحش ابن أتان . وعن الثلاثين من الفضة التي أخذها يهوذا الإسخريوطى أجرة تسليمه سيده إلى اليهود ، وعلي حزن بني إسرائيل الذين لم يؤمنوا به كما تنبأ بأشياء كثيرة غير هذه وهو النبي الذي قتل بين الهيكل والمذبح وقد دفن بأورشليم في مقبرة الأنبياء . صلاته تكون معنا امين." } },
      { kind: 'reading', text: { en: "In exile, he started to prophesy, in the second year of King Darius, 520 B.C. He prophesied about \"Jeshua, the son of Jozadak,\" and \"Zerubbabel, the son of Shealtiel,\" that they would rebuild the temple. (Ezra 5:1; 6:14)", ar: "" } },
      { kind: 'reading', text: { en: "He prophesied also about the entrance of the Lord to Jerusalem riding a donkey, the foal of a donkey (Zechariah 9:9); the thirty pieces of silver that Judas Iscariot received to deliver his Master to the Jews ( 26:14-15); the scattering of the disciples on the night of the crucifixion; the coming of Christ in glory; and the grief of the children of Israel who did not believe in Him (Zechariah 12:10). He also prophesied about many other things.", ar: "" } },
      { kind: 'reading', text: { en: "He was the prophet who was killed between the altar and the temple. He was buried in Jerusalem in the tomb of the prophets.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-16",
    title: { en: "Amshir 16", ar: "16 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "Departure of St. Elizabeth", ar: "نياحة القديسة اليصابات أم يوحنا المعمدان" } },
      { kind: 'reading', text: { en: "On this day the upright and righteous St. Elizabeth, mother of St. John the Baptist, departed. This\r\nholy woman was born in Jerusalem to a righteous father called Matthan from the tribe of Levi and\r\nfrom the house of Aaron the priest. Her mother's name was Sofia.\r\nMatthan had three daughters. The first was called Mary, the mother of Salome, the midwife who\r\ncared for the Virgin St. Mary during her virginal birth. The name of the second daughter was\r\nSofia, the mother of St. Elizabeth, the mother of St. John the Baptist. The youngest daughter was\r\nSt. Hannah, the mother of the Virgin St. Mary, the mother of the Savior. Therefore, Salome,\r\nElizabeth and the Virgin St. Mary were cousins.", ar: "في مثل هذا اليوم تنيحت الصديقة البارة أليصابات أم يوحنا المعمدان . وقد ولدت هذه القديسة بأورشليم من أب بار اسمه متثات من سبط لاوي من بيت هارون ، واسم أمها صوفية . وكان لمتثات ثلاث بنات اسم الكبرى مريم وهي أم سالومي التي اهتمت بالعذراء مريم أثناء الميلاد البتول . واسم الثانية صوفية وهي أم القديسة أليصابات والدة يوحنا المعمدان . والصغرى هي القديسة حنة والدة العذراء مريم أم المخلص . فتكون إذن سالومي وأليصابات والسيدة العذراء مريم بنات خالات . فلما تزوج القديس زكريا الكاهن بالقديسة أليصابات ، سار الاثنان بالبر والقداسة أمام الله كما يقول البشير عنهما &quot; وكان كلاهما بارين أمام الله سالكين في جميع وصايا الرب وأحكامه بلا لوم &quot; وكانت هذه البارة عاقرا . فداومت مع بعلها علي الطلبة إلى الله فرزقهما القديس يوحنا الصابغ . وقد تباطأ الله تعالي عن أجابتهما سريعا لكي يكمل الوقت الذي تحبل فيه العذراء مريم بكلمة الله . إذ انه لما تقدم الاثنان في العمر ، أرسل الله ملاكه جبرائيل إلى زكريا فبشره بحبل أليصابات بيوحنا ، واعلمه بما يكون من أمر هذا القديس . و لما زارت العذراء مريم القديسة أليصابات لتبارك لها بثمر بطنها ، تهلل القديس يوحنا وهو جنين في بطن أمه وامتلأت أليصابات من النعمة . ولما ولدت يوحنا زال العار عنها وعن عشيرتها . ولما أكملت أيامها بالبر والطهارة والعفاف تنيحت بسلام . صلاتها تكون معنا . ولربنا المجد دائما أبديا امين ." } },
      { kind: 'reading', text: { en: "When St. Zacharias the priest married St. Elizabeth, they lived in righteousness and holiness\r\nbefore God, as the evangelist said, \"They were both righteous before God, walking in all the\r\ncommandments and ordinances of the Lord blameless.\" (Luke 1:6)", ar: "" } },
      { kind: 'reading', text: { en: "This upright woman was barren. She and her husband continually supplicated God who gave them\r\nSt. John the Baptist. God was slow in answering their prayers until the time when the Virgin Mary\r\nconceived with the Word of God. When they were stricken in age, God sent His angel Gabriel to\r\nZacharias to announce to him, \"Your wife Elizabeth will bear you a son, and you shall call his\r\nname John,\" (Luke 1:13) and the angel told him what would become of St. John.", ar: "" } },
      { kind: 'reading', text: { en: "The Virgin St. Mary visited St. Elizabeth to congratulate her on her pregnancy. \"And it happened,\r\nwhen Elizabeth heard the greeting of Mary, that the babe leaped in her womb, and Elizabeth was\r\nfilled with the Holy Spirit.\" (Luke 1:41) When she gave birth to St. John, the shame of her\r\nbarrenness was lifted up from her and her people. When she completed her days in purity,\r\nrighteousness and chastity, she departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "Her intercession be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-17",
    title: { en: "Amshir 17", ar: "17 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Mina (Menas), the Monk.", ar: "استشهاد القديس انبا مينا الراهب" } },
      { kind: 'reading', text: { en: "On this day St. Mina the monk was martyred. This saint was born in Akhmim to Christian parents who were farmers. Since his youth, his heart was inclined to renounce the world, so he became a monk in one of the monasteries of Akhmim.", ar: "في مثل هذا اليوم استشهد القديس مينا الراهب . ولد هذا القديس بإحدى بلاد أخميم من أبوين مسيحيين يعيشان علي الفلاحة . ومنذ حداثته مال قلبه إلى ذهد العالم ، فترهب بأحد أديرة أخميم وأقام مدة يصوم يومين يومين ناسكا في طعامه وشرابه ثم انتقل إلى بلاد الاشمونين وأقام في دير هناك ست عشرة سنة لم يغادر خلالها الدير . فلما ملك العرب البلاد وسمع بأنهم ينكرون إن يكون لله ابن من طبيعته وجوهره مساو له في الأزلية ، عز عليه هذا القول واستأذن رئيس الدير وذهب إلى الأشمونين وتقدم إلى قائد العسكر وقال له أحقا تقولون إن ليس لله ابن من طبيعته وجوهره ؟ فقال له : نعم نحن ننفي عن الله هذا القول ونتبرأ منه . فقال له القديس إنما يجب إن نتبرأ منه إذا كان ذلك عن طريق التناسل الأبوي ولكن اعتقادنا إن الرب يسوع اله من اله ، نور من نور . فقال له هذا في شريعتنا كفر. فقال له القديس اعلم إن الإنجيل يقول الذي يؤمن بالابن له حيوة أبدية والذي لا يؤمن بالابن لن يري حيوة بل يمكث عليه غضب الله . فغضب القائد من هذا القول وأمر جنوده فقطعوا القديس بالسيوف أربا وطرحوه في البحر . فجمع المؤمنون أجزاء جسده وكفنوه ودفنوه ورتبوا له تذكار في مثل هذا اليوم . صلاته تكون معنا ولربنا المجد دائما أبديا امين ." } },
      { kind: 'reading', text: { en: "For a period of time, he fasted two days at a time and he was ascetic in his food and drink. Then he went to El-Ashmounein and dwelt in a monastery there for 16 years without leaving it.", ar: "" } },
      { kind: 'reading', text: { en: "When the Arabs ruled the country, St. Mina heard that they denied that God had a Son from His nature and essence, and equal with Him in Eternity. This denial of faith was painful to the saint, so he took permission from the abbot of the monastery and went to El-Ashmounein.", ar: "" } },
      { kind: 'reading', text: { en: "He came before the commander of the Arab camp and asked him, \"Is it true that you say that God has no Son from His nature and essence?\" The commander replied saying, \"We deny that saying about God and totally reject it.\" The saint told the Arab commander that it should only be rejected if His Son was born through parental procreation, but our belief is that the Lord Christ is God of God, and Light of Light. The commander replied, \"In our faith, this is blasphemy.\" The saint told him that the Bible says, \"He who believes in the Son has everlasting life; and he who does not believe in the Son shall not see life, but the wrath of God abides in him.\" (John 3:36)", ar: "" } },
      { kind: 'reading', text: { en: "The commander became enraged at this and ordered his soldiers to cut the saint into pieces and to throw him into the sea. The believers gathered the pieces of his body, shrouded and buried it. They arranged a commemoration of St. Mina the monk on this day.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-18",
    title: { en: "Amshir 18", ar: "18 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Malatius the Confessor, Patriarch of Antioch.", ar: "نياحة القديس ميلاتيوس المعترف بطريرك انطاكية" } },
      { kind: 'reading', text: { en: "On this day of the year 381 A.D., St. Malatius (Miltius) the Confessor, Patriarch of Antioch, departed. He was ordained a bishop for Sebaste in the year 357 A.D. He left it because of the rudeness of its people and lived a solitary life nearby the city of Halab in Syria. In the year 360 A.D., he was chosen a patriarch for Antioch during the days of Constantius, the son of Constantine the Great.", ar: "في مثل هذا اليوم من سنة 381 م تنيح القديس ميلاتيوس المعترف بطريرك إنطاكية . وقد رسم سنة 357 م أسقفا علي سبسطية ولخشونة شعبها تركها وانفرد قرب مدينة حلب بالشام ، وفي سنة 360 م انتخبوه بطريركا علي إنطاكية في ايام قسطنديوس بن قسطنطين الكبير . كان رجلا فاضلا عالما وديعا محبوبا من الجميع . فلما دخل مدينة إنطاكية ظل ثلاثين يوما وهو يقاوم الأريوسيين ويبعدهم عن الكنائس . فلما سمع الملك بذلك نفاه في نفس السنة التي ارتقي فيها البطريركية ، فاجتمع عظماء إنطاكية والأساقفة والكهنة وكتبوا للملك يطلبون رجوع القديس ، فأعاده إليهم حياء منهم ، ولكنه لما عاد سنة 362 م لم يكف عن مقاومة الأريوسيين ، وحرمهم وكل من يقول بقولهم مبينا لهم أخطاءهم وموضحا لهم بتجديفهم ، معلنا وكارزا ومثبتا إن الابن من جوهر الآب مساو له في الجوهر والربوبية . فعاد أشياع اريوس ووشوا به لدي الملك فنفاه مرة ثانية إلى بلاد ابعد من التي نفي إليها أولا . وعند وصوله إلى منفاه سمع به الأساقفة والأباء المنفيون من مختلف البلدان ، فاجتمعوا به وأقاموا معا . أما هو فلم يفتر عن التعليم وتفسير معاني الكتب الغامضة . وكانت رسائله تصل إلى رعيته مع بعد المسافة مثبتا فيها ذكر الثالوث الأقدس ، وكارزا بإيمان مجمع نيقية ، داحضا تعاليم اريوس. وقد أقام في المنفي سنين كثيرة ثم عاد إلى إنطاكية سنة 378 م وشهد مجمع القسطنطينية المسكوني سنة 381 م ثم تنيح بسلام . وقد مدحه القديس يوحنا ذهبي الفم في يوم عيده ، مبينا عظم مقداره ، وانه ليس اقل من الرسل نظرا لما ناله من النفي والإهانة من اجل الإيمان المستقيم . صلاته تكون معنا ولربنا المجد دائما أبديا امين." } },
      { kind: 'reading', text: { en: "He was an eminent, learned and meek man, who was loved by everyone. When he entered the city of Antioch, he resisted the Arians and kept them away from the churches. When the Emperor heard that, he exiled him in the same year that he was enthroned patriarch. The noble men of the city of Antioch, the bishops and the priests met and wrote to the Emperor asking for the return of the Patriarch. The Emperor returned St. Malatius in shame to them.", ar: "" } },
      { kind: 'reading', text: { en: "When St. Malatius came back in the year 362 A.D., he did not cease resisting the Arians, excommunicating them and all those who believed in their doctrines. He made clear to them their errors and explained to them their blasphemy. He declared, preached and confirmed that the Son was of the same essence as the Father, consubstantial with Him in essence and in Godship. The followers of Arius returned to slander St. Malatius before Emperor Valens, who exiled him again to a country further away than the one to which he was exiled first. When he arrived to his exile, the bishops and the fathers that were exiled from different countries came and gathered around and stayed with him.", ar: "" } },
      { kind: 'reading', text: { en: "St. Malatius did not slack in teaching and interpreting what was difficult to understand in the Holy Scriptures. His epistles reached his flock, in spite of the distance, confirming their faith in the Holy Trinity, preaching the faith of the Council of Nicea and refuting the teachings of Arius.", ar: "" } },
      { kind: 'reading', text: { en: "He was in exile for many years until his return to Antioch in the year 378 A.D. He was present in the Council of Constantinople in the year 381 A.D. Then he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "praised St. Malatius on his feast day declaring his greatness and that he was not in any less stature than the apostles in honor for what he suffered from exile and humiliation for the sake of the Orthodox faith.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-19",
    title: { en: "Amshir 19", ar: "19 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Relocation of the Relics of St. Martianus, the Monk.", ar: "نقل اعضاء القديس مرتيانوس الراهب" } },
      { kind: 'reading', text: { en: "On this day we commemorate the relocation of the relics of St. Martianus (Martinianus) the fighter monk from Athens to Antioch. After he led an adulterous woman to repentance and then to monasticism, he placed her in one of the convents. Then he went to an island and visited many countries. Finally, he came to the city of Athens where he stayed for a short while, until he fell sick and departed in peace(1).", ar: "في هذا اليوم نعيد بتذكار نقل أعضاء القديس مرتينيانوس الراهب المجاهد من اثنيا إلى إنطاكية . و ذلك انه بعد إن اجتذب امرأة زانية إلى التوبة فالرهبانية تركها في أحد الأديرة و مضي إلى الجزيرة و طاف بلادا كثيرة . و أخيرا جاء إلى مدينة أثينا فأقام بها أياما قلائل إلى إن اعتل جسده و تنيح بسلام و قد اهتم ينقل جسده القديس ديمتريوس بطريرك إنطاكية في عهد الملك فاليريانوس الوثني ، إذ أرسل كهنة إلى مدينة أثينا فحملوا جسد القديس مرتينيانوس إلى إنطاكية بإكرام و تبجيل عظيمين ثم وضعه في صندوق و رسم إن يعيد له كل سنة في مثل هذا اليوم . صلاته تكون معنا و لربنا المجد دائما أبديا امين." } },
      { kind: 'reading', text: { en: "St. Demetrius, Patriarch of Antioch, took on the endeavor to relocate the relics of the saint during the reign of Emperor Valens the Infidel. St. Demetrius sent priests to Athens. They carried the body of St. Martianus with great honor to Antioch. He placed the body in a sarcophagus and appointed a feast to celebrate him on this day.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-20",
    title: { en: "Amshir 20", ar: "20 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Peter, 21st Pope of Alexandria.", ar: "نياحة البابا بطرس الثانى الإسكندرى" } },
      { kind: 'reading', text: { en: "On this day of the year 370 A.D., the blessed father Abba Peter II, 21st Pope of Alexandria, departed. He was the successor of St. Athanasius the apostolic, who was his teacher. Anba Peter II suffered many tribulations from the followers of Arius who often tried to kill him, but he escaped them.", ar: "في مثل هذا اليوم من سنة 370 م تنيح الاب القديس المغبوط الانبا بطرس الثاني بابا الإسكندرية الحادي والعشرون . وقدم بطريركا بعد القديس أثناسيوس الرسولي معلمه ، وقد قاسي شدائد كثيرة من اتباع اريوس ، الذين حاولوا قتله مرارا ، فكان يهرب منهم وظل مختفيا مدة سنتين أقاموا خلالها واحد منهم بدله اسمه لوكيوس ، غير إن المؤمنين تمكنوا من إبعاد لوكيوس الدخيل، وإعادة الاب بطرس حيث أقام في كرسيه ست سنين مضطهدا مقاوما . ولما كمل له ثماني سنين نقله الرب من أتعاب هذا العالم ومضي إلى النعيم الدائم . صلاته تكون معنا امين." } },
      { kind: 'reading', text: { en: "He was forced to hide for two years, during which the Arians put in his place one of them named Lucius. Nevertheless, the believers were able to remove Lucius, the false pope, and brought back Anba Peter who remained on his chair for 6 years of persecution, during which he resisted the Arians. When he completed 8 years, the Lord relieved him from the toil of this world and he departed to the eternal bliss.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of Sts. Basil, Theodore and Timothy, the Martyrs.", ar: "تذكار القديسين باسيليوس وثاؤذورس وتيموثاوس" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of Saints Basil, Theodore and Timothy, the martyrs, in the city of Alexandria.", ar: "وفي هذا اليوم تذكار القديسين باسيليوس وثاؤذورس وتيموثاوس الشهداء بمدينة الإسكندرية. صلاتهم تكون معنا ولربنا المجد دائما ابديا امين" } },
      { kind: 'reading', text: { en: "Their prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-21",
    title: { en: "Amshir 21", ar: "21 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Virgin St. Mary.", ar: "التذكار الشهري لوالدة الاله القديسة مريم العذراء" } },
      { kind: 'reading', text: { en: "We celebrate on this day the commemoration of the pure Lady , the Mother of God, the Word, through whom was the salvation of Adam and his offspring.", ar: "فى مثل هذا اليوم نعيد بتذكار السيدة العذراء الطاهرة البكر البتول الذكية مريم والدة الإله الكلمة أم الرحمة، الحنونة شفاعتها تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "Her intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Zacharias, Bishop of Sakha.", ar: "نياحة انبا زخارياس اسقف سخا" } },
      { kind: 'reading', text: { en: "On this day also St. Zacharias, Bishop of Sakha, departed. He was the son of a scribe called John who left his job and was chosen to be a priest. His son Zacharias was raised on studying literary and religious subjects.", ar: "في مثل هذا اليوم تنيح القديس زخارياس أسقف سخا. كان ابن كاتب اسمه يوحنا ، ترك وظيفته واختير قسا ، فنشا ابنه زخارياس علي تلقي العلوم الأدبية والدينية ولما كبر عينه الوزير كاتبا بديوانه وبعد ذلك اتفق مع صديق له يسمي ابلاطس وكان واليا علي سخا ، إن يتركا عملهما ويذهبا إلى البرية ويترهبا . واتفق حضور أحد رهبان دير القديس يحنس القصير ، فعزما إن يذهبا معه إلى ديره ، فلما علم الوالي بذلك منعهما ، وبعد ايام قليلة رأى الاثنان رؤيا كمن يقول لهما لماذا لم تتمما النذر الذي قررتماه ، فخرجا توا خفية وسارا إلى البرية وهما لا يعرفان الطريق فاتفق إن قابلهما أحد الرهبان فاصطحبهما إلى دير القديس يحنس ، فلما علم أصدقاؤهما اخذوا من الوالي كتابا ليرجعوهما ، فبدد الرب مشورتهم ، أما زخارياس وصديقه فقد لبسا الثوب الرهباني واجهدا نفسيهما في عبادات كثيرة . وكان ذلك في زمان القديسين أنبا ابرام وأنبا جورجي اللذين كانا خير مرشد لهما . ولما تنيح أسقف سخا كتب الشعب إلى الاب البطريرك يطلبون زخارياس ليكون أسقفا عليهم ، فاستحضره وسامه رغما عنه. وقد حدث وقت السامة انه عندما هم الاب البطريرك بوضع يده علي راس زخارياس إن سطع نور في الكنيسة وظهر وجهه كنجم بهي. ولما حضر إلى كرسيه فرح به الشعب وخرج للقائه بمنتهى الإجلال ، فاستضاءت الكنيسة به . وكان هذا الاب فصيحا ممتلئا من النعمة ، فوضع عدة مقالات ومواعظ وميامر . وأقام علي كرسيه ثلاثين سنة ثم تنيح بسلام" } },
      { kind: 'reading', text: { en: "When he grew up, El-Wazeer appointed him as a scribe in his court. Afterward he agreed with a friend called Ptolemy who was the prefect of the town of Sakha, to leave their work and go to the wilderness to become monks. That coincided with the coming of a monk from the monastery of , so they decided to go with him to the monastery. When the ruler (El-Wazeer) knew about that, he prevented them from going to the monastery.", ar: "صلاته تكون معنا ولربنا المجد دائما ابديا امين ." } },
      { kind: 'reading', text: { en: "A few days later, they saw a vision as if someone was asking them, \"Why did you not fulfill your vow?\" Immediately, they left in secret, walking to the wilderness, without knowing their way. They met on their way, by the will of God, a monk who took them to the monastery of St. John the Short (Colobos). When their friends knew about that, they took a letter from the Governor to bring them back, but the Lord defeated their counsel. As for Zacharias and his friend, they put on the garb of the monks and exerted themselves in many worships. That was during the time of the saints Abba Gawargah and Abba Abraham who were the best guides for them.", ar: "" } },
      { kind: 'reading', text: { en: "When the Bishop of Sakha departed, the people wrote to the father, the Patriarch, asking for Zacharias to be their bishop. The Patriarch brought him and ordained him against his will. At the time of the ordination, when the Pope was about to put his hands on Zacharias' head, a light shined in the church and his face appeared as a bright star.", ar: "" } },
      { kind: 'reading', text: { en: "When he arrived to his diocese, the people rejoiced and went out to meet him with great honor. The church was illumined with his teachings. St. Zacharias was eloquent and filled with grace and he wrote many articles, sermons and discourses. He stayed on his chair for 30 years, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Onesimus, the Disciple of St. Paul.", ar: "استشهاد القديس انسيموس تلميذ القديس بولس الرسول" } },
      { kind: 'reading', text: { en: "On this day also St. Onesimus, the disciple of St. Paul, was martyred. This saint was a slave for a man from Rome called Philemon who believed at the hands of St. Paul, when he heard his preaching in Rome.", ar: "في مثل هذا اليوم أستشهد القديس انسيموس تلميذ القديس بولس الرسول. كان هذا القديس مملوكا لرجل من رومية اسمه فليمون الذي كان قد آمن علي يد القديس بولس لدي سماعه تبشيره في رومية . وحدث إن سافر فليمون من رومية لأعمال خاصة فاستصحب انسيموس ضمن غلمانه ، وهناك اغوي الشيطان انسيموس فسرق بعض مال سيده وهرب إلى رومية . واتفق بالإرادة الإلهية إن حضر انسيموس تعليم القديس بولس الرسول فحفظه في قلبه وآمن علي يديه وإمتلأ قلبه بالنعمة وخوف الله ، فتذكر ما سرقه من سيده ومن غيره ، ولم يبق معه منه شئ يعيده إلى أربابه. فحزن وأعلم الرسول بولس بذلك . فطمأنه وكتب رسالة إلى سيده فليمون ، اعلمه فيها إن انسيموس قد اصبح تلميذا للمسيح ، وابنا لبولس بالبشارة ، ويوصيه إن يترفق به ولا يؤاخذه بل يحسب ما خسره كأنه علي الرسول . فلما أوصل انسيموس الرسالة إلى سيده فليمون فرح بإيمانه وتوبته وعامله كوصية الرسول . وزاد علي ذلك بان قدم له مالا أخراً فلم يقبل قائلا انا استغنيت بالمسيح ثم ودعه وعاد إلى رومية . واستمر خادما للقديس بولس إلى حين شهادته واستحق إن يقدم كاهنا . وبعد استشهاد القديس بولس قبض عليه حاكم رومية ونفاه إلى إحدى الجزائر فمكث هناك يعلم ويعمد أهل الجزيرة . ولما حضر الحاكم إلى تلك الجزيرة ووجده يرشد الناس إلى الإيمان بالسيد المسيح ضربه ضربا موجعا ثم كسر ساقيه فتنيح بسلام . صلاته تكون معنا امين." } },
      { kind: 'reading', text: { en: "Philemon departed from Rome on a business trip and took with him Onesimus among others of his servants. There the devil enticed Onesimus, so he stole money from his master and fled to Rome. According to the Divine Will, Onesimus attended the preaching of St. Paul, which he kept in his heart. He believed at the hand of St. Paul and his heart was filled with the grace and the fear of God. He remembered what he stole from his master and from others and since he did not have anything left from the stolen money to return to its rightful owners, he was sorrowful and told St. Paul about that.", ar: "" } },
      { kind: 'reading', text: { en: "St. Paul comforted him and wrote an epistle to Onesimus' master, Philemon, informing him in it, that Onesimus became a follower of Christ saying, \"I appeal to you for my son Onesimus, whom I have begotten while in my chains.\" St. Paul asked him to treat him gently and not to mind what he did but to consider what he lost as owed by the apostle.", ar: "" } },
      { kind: 'reading', text: { en: "When Onesimus took the epistle to his master Philemon, he was pleased by his faith and repentance and treated him as the apostle commanded. Furthermore, he offered him more money but St. Onesimus refused saying, \"I am rich with Christ.\" Then he bid Philemon farewell and returned to Rome.", ar: "" } },
      { kind: 'reading', text: { en: "St. Onesimus continued to serve St. Paul until his martyrdom and deserved to be ordained a priest. After the martyrdom of St. Paul, the governor of Rome seized him and exiled him to one of the islands. He remained there preaching and baptizing the people of the island. When the governor came to the island, he found him guiding the people to the belief in the Lord Christ. He was beaten severely and his legs were broken. He departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Gabriel, 57th Pope of Alexandria.", ar: "نياحة البابا غبريال بابا الاسكندرية السابع و الخمسون" } },
      { kind: 'reading', text: { en: "On this day also of the year 911 A.D., the great father St. Gabriel, 57th Pope of Alexandria, departed. This saint became a monk at a young age, practicing many worships. He loved solitary life and wept much while praying, asking the Lord to save him from the snares of the devil.", ar: "في مثل هذا اليوم من سنة 911 م تنيح الاب العظيم القديس غبريال بابا الإسكندرية السابع والخمسون وقد ترهب هذا القديس منذ حداثته وقام بعبادات كثيرة . وكان محبا للانفراد والوحدة . وكان يكثر من البكاء في الصلاة طالبا من الله إن ينجيه من مكائد الشيطان." } },
      { kind: 'reading', text: { en: "When Pope Mikhael, 56th Pope, departed, they chose this father to be the Pope in his place. He was ordained in the year 900 A.D. against his will. He cared for the church affairs well, and the duties of the patriarchate did not prevent him from his worship and asceticism.", ar: "و لما تنيح البابا ميخائيل السادس والخمسون وقع الاختيار علي هذا الاب ليكون بطريركا مكانه فرسم سنة 900 م رغما عنه. فاخذ يهتم بشئون الكنيسة ولم تمنعه مهام البطريركية عن عبادته ونسكه، إذ كان يقضي اغلب الأيام في البرية . وإذا جد ما يستدعي قيامه إلى مصر أو الإسكندرية كان يذهب ثم يعود إلي الصوم والسهر والصلاة والتواضع . وكان يستيقظ في الليل ويأخذ مجرفة من حديد ويلبس ثوبا رثا ويمر علي دورات المياه التي بالقلالي فيغسلها وينظفها . وأقام علي هذا الحال عدة سنين حتى نظر الله إلى تواضعه وانسحاق قلبه فرفع عنه الآلام ومنحه نعمة الانتصار علي الخطية والذات . وأقام هذا الاب عابدا ومجاهدا وواعظا إحدى عشر سنة ثم تنيح بسلام. صلاته تكون معنا امين." } },
      { kind: 'reading', text: { en: "He spent most of his days in the wilderness and whenever he had some affairs to take care of in Cairo or Alexandria, he would leave and then return back to the wilderness. He fought against the flesh and the devil by increasing fasting, watching, prayers and humility. He used to wake up in the night, put on a ragged garment, take a metal shovel and go around the bathrooms of the monks' cells, washing and cleaning them. He did the same for many years until the Lord looked upon his humility and humble heart, so He relieved his pains and gave him the grace of victory over sin and the body. This father was a worshipper, fighter and a preacher for 11 years, then he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نوة السلوم : شمالية جنوبية شرقية ممطرة يومان" } },
      { kind: 'reading', text: { en: "", ar: "في اشهر الشتاء تتعرض الأجزاء المطلة علي البحر المتوسط لظاهرة تولد الانخفاضات الجوية الإعصارية التي تميز الأحوال المناخية في إقليم البحر المتوسط وتعرف في الإسكندرية باسم النوات." } },
      { kind: 'reading', text: { en: "", ar: "هي اضطرابات جوية تنشأ عنها دوامة هوائية دائرية أو بيضاوية ذات ضغط منخفض وسط مساحة ضغطها مرتفع وتندفع فيها الرياح علي شكل حلزوني نحو مركز منخفض بحيث يكون سيرها ضد اتجاه عقارب الساعة ." } }
    ],
  },
  {
    id: "synax-amshir-22",
    title: { en: "Amshir 22", ar: "22 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Maruta (Maruthas) the Bishop.", ar: "استشهاد القديس ماروتا اسقف ميافرقين" } },
      { kind: 'reading', text: { en: "On this day the church commemorates the departure of St. Maruta (Maruthas), bishop of Marjferqat (Mia Farcane(1)), and the relocation of the relics of the saints who were martyred there in the days of Emperor Diocletian.", ar: "في هذا اليوم تذكار نياحة القديس ماروتا أسقف ميافرقين ونقل أعضاء القديسين الذين استشهدوا بها ايام دقلديانوس. وكان ماروتا رجلا عالما فاضلا ولذلك وقع اختبار الملك الكبير ثاؤدسيوس أبو اركاديوس واونوريوس ، لإرساله إلى ملك الفرس لمفاوضته في أمر الهدنة التي كانا يرغبان في توقيعها . فاكرم سابور الملك وقادته ، واسكنه في قصر ملكي ولما علم ماروتا إن للملك ابنة مجنونة طلب إحضارها إليه وصلي عليها فبرئت وفرح سابور بذلك وزاد في إكرامه فطلب القديس من الملك أجساد القديسين الذي استشهدوا في بلاد فارس يأذن له بذلك فأخذها وبني لها كنيسة ثم حصنا كبيرا حولها . وفيما بعد بنيت مدينة داخل ذلك الحصن دعوها باسمه ماروتا . وبعد إن أتم عمله عاد إلى الملك ثاؤدسيوس وأتقام إلى إن تنيح برومية ." } },
      { kind: 'reading', text: { en: "St. Maruthas was a knowledgeable and righteous man. For this reason, Emperor Theodosius, father of Arcadius and Honorius, selected him to serve as a good will ambassador to the king of Persia, Sapor II, to negotiate with him the conditions of the truce that both wanted to sign. King Shapur (Sapor) welcomed him and housed him in a royal palace.", ar: "صلاته تكون معنا ولربنا المجد دائما ابديا امين." } },
      { kind: 'reading', text: { en: "When St. Maruthas knew that the king had a demented daughter, he asked to bring her to him. He prayed over her and she was healed. King Shapur was overjoyed and became more courteous to St. Maruthas.", ar: "" } },
      { kind: 'reading', text: { en: "The saint asked the King for the relics of the saints who were martyred in Persia, and the King gave him permission to take them. The saint took the relics for which he built a church and a great fortress around it. Later on, a city was built inside the walls of the fortress, which was named after Maruthas.", ar: "" } },
      { kind: 'reading', text: { en: "After the saint had finished his mission, he returned to Emperor Theodosius, and stayed in Rome until his departure.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and to our God is the Glory forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-23",
    title: { en: "Amshir 23", ar: "23 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Eusebius, Son of Basilides, the Minister.", ar: "استشهاد القديس اوساويوس ابن واسيليدس الوزير" } },
      { kind: 'reading', text: { en: "On this day, St. Eusebius, the son of , was martyred. This Saint was one of the soldiers who fought in the war against Persia. When Diocletian abandoned the faith, Basilides, informed his son, Eusebius, of what Diocletian had done. Then St. Eusebius in turn told his companions, the holy men: Abadir, Yustos, Ecladius, and Theodore about this matter. They all agreed to shed their blood in the Name of the Lord Christ.", ar: "في مثل هذا اليوم استشهد القديس اوساويوس ابن القديس واسيليدس الوزير وكان هذا القديس أحد الجنود في الحرب ضد الفرس ولما ارتد دقلديانوس اخبره أبوه واسيليدس بما كان من أمر دقلديانوس فاعلم اوساويوس أقاربه القديسين أبادير ويسكس واقلاديوس وثاؤودورس بهذا فتحالفوا جميعا علي إن يسفكوا دماءهم علي اسم السيد المسيح . ولما انتهي القتال وعادوا إلى إنطاكية حاملين علم الغلبة والظفر ، خرج الملك للقائهم . وبعد ذلك عرض عليهم عبادة الأوثان مثله فرفضوا جميعا ثم تقدم اوساويوس وجرد سيفه وهم بقتل دقلديانوس ومن معه فهرب من أمامه واختفي ولولا وجود وزيره واسيليدس لكان القديسون اهلكوا كل كبار الدولة ، فأشار رومانوس أحد الوزراء علي الملك بنفي القديس اوساويوس إلى ارض مصر ليقتل هناك فتم ذلك وأرسلوه إلى موريانوس والي فقط الذي عذبه كثيرا بالهنبازين وتقطيع الأعضاء والضرب الشديد . وكان الرب يرسل إليه ملاكه فيقويه في جميع شدائده ويعزيه ويشفي جراحاته . ثم أراه في رؤيا الفردوس مساكن القديسين والمواضع التي أعدت له ولأبيه ولأخيه ففرحت نفسه جدا . وبعد ذلك أمر الوالي بحرقه في أتون خارج مدينة اهناس فنزل ملاك الرب وأطفأ اللهيب واخرج القديس سالما وأخيرا أمر الوالي بقطع رأسه حيث ونال إكليل الشهادة . صلاته تكون معنا ولربنا المجد دائما ابديا امين." } },
      { kind: 'reading', text: { en: "When the war was over, they returned to Antioch carrying the flag of victory. The Emperor went out to meet them, and asked them to worship his idols with him, but they all refused. Eusebius pulled his sword out, and tried to kill Diocletian and all who were with him, but Diocletian fled and disappeared. If not for the presence of Basilides, Eusebius and the saints with him could have killed all the leaders of the government.", ar: "" } },
      { kind: 'reading', text: { en: "Romanus, one of the ministers of the Emperor, advised him to exile Eusebius to Egypt to be killed there. He sent him to the governor of Qift (Coptos), Maurianus, who inflicted upon him many tortures from the Hinbazeen (the squeezing wheel), dismemberment, and by severe beatings.", ar: "" } },
      { kind: 'reading', text: { en: "The Lord sent to him His angel to strengthen him in his afflictions, to comfort him and to heal his wounds. The Lord showed him in a vision the paradise and the mansions of the saints, and the places that had been prepared for him, his father and his brother, and his soul exceedingly rejoiced.", ar: "" } },
      { kind: 'reading', text: { en: "The Governor ordered him to be burned in a fiery furnace outside the City of Ahnas. The angel of the Lord came and put out the fire and took St. Eusebius out safely. Finally the Governor ordered him beheaded and thus he received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-24",
    title: { en: "Amshir 24", ar: "24 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Agapetus (Agapius), the Bishop.", ar: "نياحة القديس اغابيطوس الأسقف" } },
      { kind: 'reading', text: { en: "On this day St. Agapetus (Agapius), the bishop, departed. He was born of Christian parents during the time of the infidel emperors Diocletian and Maximianus. His parents brought him up in a Christian upbringing, and he was ordained a deacon. Then, he went to one of the monasteries and served the elders therein. He learned from them worship and asceticism and was accustomed to fasting and prayer. His food was legumes to break the fast. He grew in his ascetic life and in every virtue, and God wrought through him many miracles, among which were the following:", ar: "هذا اليوم تنيح القديس اغابيطوس الاسقف و قد ولد من ابوين مسيحيين في زمان الملكين الوثنيين دقلديانوس و مكسيميانوس ، فربياه تربية مسيحية و قدماه شماسا ثم مضي الي احد الاديرة و خدم الشيوخ الذين فيه و تعلم منهم العبادة و النسك و تعود المواظبة علي الصوم و الصلاة . و كان غذاؤه بعد الصوم قليلا من الترمس و ازداد في نسكه و تقدم في كل فضيلة و اجري الله علي يديه ايات كثيرة منها انه شفي صبية اضناها المرض و عجز الاطباء عن علاجها . و صلي مرة فاهلك الله وحشا كان يفتك بالناس و بصلات منح الله الشفاء لكثيرين من المرضي . فشاع خبر نسكه و فضله و قوة صلاته و سمع بذلك ليكينيوس الوالي فاستحضره كرها و عينه جنديا فيم يمنعه هذا من مداومة النسك و العبادة بل ازداد في الفضيلة. و بعد قليل اهلك الله دقلديانوس و ملك بعده الملك المحب لله قسطنطين الكبير و كان القديس يتمني لو يطلق سراحه و يرجع الي ديره و قد اجاب الله امنيته اذ انه كان لقسطنطين الملك غلام عزيز لديه جدا لما عليه من الخصال الحميدة و قد اصابه روح نجس كان يعذبه كثيرا فاشار عليه بعض اصدقائه إن يلجا الي اغابيطوس ليصلي لاجله فيشفي . فاستغرب إن يكون بين الجنود من له هذه الموهبة ، و ارسل الملك في الحال فاستدعاه و صلي علي الغلام و رشم عليه علامة الصليب المقدس فشفاه الله . ففرح الملك بذلك و اراد مكافاته فلم يقبل الا اطلاقه من الجندية ليعود الي مكان نسكه . فاجابه الي طلبه و عاد القديس الي حيث كان اولا و قصد الوحدة و بقي في موضع منفرد و بعد زمن رسم قسا. و بعد نياحة اسقف بلده طلبوا هذا القديس من رئيس الدير فسمح لهم به فرسم اسقفا و رعي رعية المسيح احسن رعاية و منح نعمة النبوة و عمل المعجزات فكان يبكت الخطاة علي ما يعملونه سرا و يوبخ الكهنة علي تركهم تعليم الشعب و وعظه . و تضمنت سيرته عمل مائة معجزة ثم تنيح بشيخوخة صالحة . صلاته تكون معنا إمين ." } },
      { kind: 'reading', text: { en: "He healed a girl from a debilitating sickness which had stricken her for a long time, and doctors had failed to cure her. He also prayed once and God destroyed a beast which was devouring people. By his prayers, God granted healing to many sick people.", ar: "" } },
      { kind: 'reading', text: { en: "The news of his asceticism, righteousness and the power of his prayer spread everywhere. When Lucinus the governor heard about St. Agapius, he brought him by force and appointed him a soldier in his army. This did not prevent St. Agapius from continuing in his ascetic life and his worship and he rather increased in virtue.", ar: "" } },
      { kind: 'reading', text: { en: "Shortly after, God perished Diocletian and the God-loving Emperor Constantine took over the empire after him. St. Agapius desired to gain his freedom and to return to his monastery, and God answered him.", ar: "" } },
      { kind: 'reading', text: { en: "Emperor Constantine had a servant who was very dear to him for the good qualities he had. The servant was stricken with an evil spirit which tormented him. Some friends of the Emperor advised him to ask Agapius, the soldier, to pray for his servant to be healed. The Emperor was surprised to know that one among his soldiers had the gift of healing. The Emperor sent for St. Agapius who prayed upon the servant, made the sign of the holy cross over him, and God healed him.", ar: "" } },
      { kind: 'reading', text: { en: "The Emperor rejoiced and wanted to reward him. St. Agapius refused to accept any reward except to be granted his release from military service to go back to the place of his worship. The Emperor granted him what he wanted. The saint returned to where he was before and he lived a solitary life. After a while, he was ordained a priest.", ar: "" } },
      { kind: 'reading', text: { en: "After the departure of the bishop of his town, the people asked for this saint from the abbot of the monastery, and he gave him his permission to leave. St. Agapius was ordained bishop and shepherded the flock of Christ with the best of care. He was granted the gift of prophecy and performing miracles. He rebuked the sinners for what they had done in secret. He rebuked the priests for forsaking teaching and instructing their flocks.", ar: "" } },
      { kind: 'reading', text: { en: "His biography included more than one hundred miracles that he had performed, and he departed at a good old age.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Timothy and St. Matthias.", ar: "استشهاد القديس تيموثاوس بغزة والقديس متياس بمدينة قوص ." } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the martyrdom of St. Timothy of Gaza, and St. Matthias of the City of Koos (Quoce).", ar: "في مثل هذا اليوم تذكار شهادة القديس تيموثاوس بغزة و القديس متياس بمدينة قوص ." } },
      { kind: 'reading', text: { en: "Their prayers be with us and Glory be to our God forever. Amen.", ar: "صلاتهما تكون معنا و لربنا المجد دائما ابديا امين" } }
    ],
  },
  {
    id: "synax-amshir-25",
    title: { en: "Amshir 25", ar: "25 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of Sts. Archippus, Philemon and Lycia the Virgin.", ar: "استشهاد ارخبس وفليمون أخية وابيفية العذراء" } },
      { kind: 'reading', text: { en: "On this day, the Sts. Archippus, Philemon and Lycia the virgin, were martyred. They believed through St. Paul when he was preaching in Phrygia.", ar: "في مثل هذا اليوم استشهد القديسون أرخبس وفليمون وابفية العذراء الذين أمنوا علي يد القديس بولس الرسول حينما كان يكرز في فريجية . واتفق إن الوثنيين كانوا يحتفلون بارطاميس في يوم عيده فدخل القديسون إلى البربا ليشهدوا ما يقوم به القوم . فرأوهم يضحون للصنم ويعظمونه فاشتعل الحب الإلهي في قلوبهم وخرجوا من البربا وتوجهوا إلى الكنيسة معلنين مجد السيد المسيح ومعظمين اسمه القدوس . ولما سمع بأمرهم بعض الوثنيين وشوا بهم لدي الوالي ، الذي هاجم الكنيسة وقبض عليهم وعذبهم بوضع مسامير محماة في النار في جنوبهم ثم طرح القديس أرخبس في حفرة وأمر برجمه حتى اسلم الروح الطاهرة أما القديسان فليمون وابفية فقد عذبوهما بأنواع كثيرة من العذابات ولم يتركوهما حتى اسلما الروح . صلاتهما تكون معنا امين ." } },
      { kind: 'reading', text: { en: "One day the pagans were celebrating the feast of Artamis. The saints entered their temple to see what they were doing and to see their rituals. They saw them offering sacrifices to the idol and glorifying it.", ar: "" } },
      { kind: 'reading', text: { en: "The divine zeal inflamed their hearts, and they went out of the temple and went to the church declaring the glory of the Lord Christ and magnifying His Holy Name. When the pagans heard about what the saints had done, they informed the Governor, who attacked the church and arrested them. He tortured the saints by driving hot nails in to their sides. He threw St. Archippus into a ditch and ordered him to be stoned until he gave up his pure spirit. St. Philemon and St. Lycia were also tortured with different kinds of tortures until they gave up their spirits.", ar: "" } },
      { kind: 'reading', text: { en: "Their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Quona (Kona) and St. Mina.", ar: "استشهاد الشماس قونا بمدينة رومية و استشهاد القديس مينا بمدينة \r\nقبرص." } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the martyrdom of the deacon Quona of the City of Rome, and the martyrdom of St. Mina of Cyprus.", ar: "في هذا اليوم تذكار شهادة الشماس قونا بمدينة رومية و شهادة القديس مينا بمدينة قبرص." } },
      { kind: 'reading', text: { en: "Their prayers be with us and Glory be to our God forever. Amen.", ar: "صلاتهما تكون معنا و لربنا المجد دائما ابديا امين ." } }
    ],
  },
  {
    id: "synax-amshir-26",
    title: { en: "Amshir 26", ar: "26 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Hosea, the Prophet.", ar: "نياحة هوشع النبى" } },
      { kind: 'reading', text: { en: "On this day, St. Hosea, the prophet, one of the twelve minor prophets of Israel, departed. This righteous man prophesied during the days of Uzziah, Jotham, Ahaz and Hezekiah, kings of Judah, and in the days of Jeroboam, the son of Joash, King of Israel. (Hosea 1:1)", ar: "في مثل هذا اليوم تنيح القديس هوشع النبي أحد الاثني عشر نبيا من أنبياء بني إسرائيل . تنبأ هذا البار في ايام عزيا ويوثام واحاز وحزقيا ملوك يهوذا وفي ايام يربعام بن يواش ملك إسرائيل وذكر في نبوته أشياء غريبة وعجيبة وبكت بني إسرائيل علي سيئاتهم وزلاتهم وأنذرهم بالشرور التي تحل بهم عقابا لهم علي جرائمهم ووعدهم بزوال هذه المصائب عنهم إذا رجعوا إلى الرب ألههم وتنبأ عن آلام المخلص وقيامته وخلاص بني البشر . فقال &quot; ضرب فيجبرنا يحيينا بعد يومين في اليوم الثالث يقيمنا فنحيا أمامه لنعرف فلنتتبع لنعرف الرب &quot; وتنبأ عن أبطال سطوة الموت وكسر شوكة الجحيم بقوله &quot; أين شوكتك يا موت أين غلبتك يا هاوية &quot; وتنيح في شيخوخة صالحة . صلاته تكون معنا امين." } },
      { kind: 'reading', text: { en: "He mentioned in his prophecy some remarkable and marvelous things. He rebuked the children of Israel for their sins and their transgressions, and warned them in advance about the evil things that would befall them because of their offenses. He promised them the uplifting of these calamities if they returned to the Lord their God.", ar: "" } },
      { kind: 'reading', text: { en: "He also prophesied about the passions of our Savior, His resurrection and the salvation of the human race. He said, \"He has torn, but He will heal us; He has stricken, but He will bind us up. After two days He will revive us; on the third day He will raise us up, that we may live in his sight. Let us know, let us pursue the knowledge of the Lord... \" (Hosea 6:1-3)", ar: "" } },
      { kind: 'reading', text: { en: "He prophesied also about the abolishment of the sting of death and the dominion of hell by saying, \"I will ransom them from the power of the grave, I will redeem them from death, O Death, I will be your plagues! O Grave, I will be your destruction.\" (Hosea 13:14) \"O Death, where is your sting? O Hades, where is your victory?\" (I Corinthians 15:55)", ar: "" } },
      { kind: 'reading', text: { en: "He departed at a blessed old age.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Zadok and the 128 who were with Him.", ar: "استشهاد القديسون صادوق و المئة و الثمانية و العشرون رجلا في \r\nبلاد الفرس" } },
      { kind: 'reading', text: { en: "On this day also, St. Zadok and the 128 saints with him were martyred in Persia. Behram, King of Persia, brought them before him and ordered them to worship the sun. St. Zadok said to him, \"I do not worship except God, the Creator of the sun and all the universe.\" The King asked, \"Does this Sun have a god?\" The saint replied, \"Yes, and He is the Lord Christ, our God.\"", ar: "في مثل هذا اليوم استشهد القديسون صادوق والمئة والثمانية والعشرون رجلا في بلاد الفرس . وذلك إن بهرام ملك الفرس أحضرهم أمامه وعرض عليهم إن يسجدوا للشمس فأجابه القديس صادوق بقوله إنني لا اسجد إلا لله خالق الشمس وكل الكون . فقال له الملك وهل لهذه الشمس اله ؟ فأجابه نعم هو السيد المسيح إلهنا . فأمر بقطع رأسه فصلي القديس وتقدم السياف فقطع رأسه فظهر عند ذلك نور عظيم رآه الحاضرون فصاحوا نحن جميعا مسيحيون فأمر الملك بضرب أعناقهم كلهم ونالوا إكليل الشهادة ." } },
      { kind: 'reading', text: { en: "The King ordered him beheaded. The saint prayed and the executioner cut his head. A great light appeared and all those who were present saw it and cried, saying, \"We are all Christians.\" The King ordered that their heads be cut off and they received the crown of martyrdom.", ar: "صلاتهم تكون معنا ولربنا المجد دائما ابديا امين ." } },
      { kind: 'reading', text: { en: "Their prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-27",
    title: { en: "Amshir 27", ar: "27 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Eustathius, Patriarch of Antioch.", ar: "نياحة القديس اوسطاثيوس بطريرك إنطاكية" } },
      { kind: 'reading', text: { en: "On this day of the year 330 A.D., St. Eustathius, Patriarch of Antioch, departed in exile. He was enthroned Patriarch of Antioch during the reign of the righteous Emperor Constantine the Great. He was righteous and well learned. He attended the Nicene Council, and the fathers gathered there agreed on excommunicating Arius and exiling him and all those who believed in his teachings. Those were Eusabius the Nicomedian; Thaoghonius, Bishop of Nicea; and Eusabius, Bishop of Caesarea.", ar: "في مثل هذا اليوم من سنة 330 م تنيح القديس أسطاثيوس بطريرك إنطاكية في منفاه وذلك انه قدم بطريركا علي إنطاكية في زمن الملك البار قسطنطين الكبير وكان عالما تقيا وشهد مجمع نيقية ووافق الأباء علي قطع اريوس ونفيه هو والقائلين بتعاليمه وهو أوسابيوس الينقوميدي وثاؤغونيوس أسقف نييقة وأوسابيوس أسقف قيسارية وبعد انتهاء المجمع وعودة الأباء إلى كراسيهم اتفق هؤلاء المقطوعين فيما بنيهم علي إن يتظاهروا بالرغبة في الذهاب إلى بيت المقدس ولكنهم ذهبوا إلى إنطاكية وهناك أغروا امرأة زانية ببعض المال ووعدوها بأكثر مقابل إن تتهم هذا القديس انه قد انجب منها ولدا . فآخذت المال وذهبت إلى الكنيسة وقالت كما لقنوها أما هم فتظاهروا بتكذيبها وقالوا لها : قدمي دليلك إن كنت صادقة فيما تقولين . نحن لا نقبل قولك إلا إذا حلفت علي الإنجيل إن هذا الذي ادعيته علي هذا الاب صحيح . فحلفت لهم ، حينئذ قالوا ليس بعد القسم شئ . ثم حكموا بسقوط القديس من درجته وابلغوا قسطنطين الملك قائلين له إن مجمع كهنة حكم بسقوط الاب أسطاثيوس بطريرك إنطاكية فصدق الملك قولهم ونفاه إلى ثراكي حيث لبث القديس بها حتى تنيح إلا إن الله لم يغفل عن إظهار الحقيقة فان المرآة قد مرضت مرضا طويلا متي نحل جسمها وتيقنت إن الذي أصابها إنما كان بسبب قذفها القديس بما ليس فيه . فاتت وأقرت أمام هل المدينة ببراءته وكذبها فيما ادعت به عليه وقالت إن هؤلاء هم الذين الجأوها إلى ذلك نظير مبلغ من المال وإن الولد الذي معها هو من رجل اسمه كاسم القديس أسطاثيوس . فأقنعوها بان تحلف وتقصد في قلبها الرجل صاحبها فتنجو من خطر الحلف كذبا وهكذا ظهرت براءة هذا القديس وعاد الكهنة إلى ذكر اسمه في القداس . وقد مدحه القديس يوحنا ذهبي الفم في يوم تذكاره. صلاته تكون معنا ولربنا المجد دائما ابديا امين." } },
      { kind: 'reading', text: { en: "After the council was concluded and the fathers went back to their parishes, those who were excommunicated pretended that they wished to go to Jerusalem, but instead they went to Antioch. There, they enticed a harlot with money and other things in order to accuse St. Eustathius the Patriarch that he fathered a child from her. She took the money and went to the church and said as they had instructed her. They pretended to disbelieve her and said, \"Bring forth your proof if you are truthful in what you are saying. We will not accept your statement unless you swear on the Bible that what you claim against this father is true.\" She swore to them and they replied, \"We do not need any more proof.\"", ar: "" } },
      { kind: 'reading', text: { en: "They condemned St. Eustathius and judged to strip him from his episcopal rank. They informed Emperor Constantine saying: \"A council of clerics judged to remove Fr. Eustathius, Patriarch of Antioch, from his office\". The Emperor believed their unfounded judgement, and he deposed and banished St. Eustathius to Thrace where the saint remained until his departure.", ar: "" } },
      { kind: 'reading', text: { en: "The Lord God, Who loves His holy servants, did not neglect to reveal the truth. The woman became ill with a debilitating long illness and suffered great pain. She realized that her suffering was a punishment for her false accusation against the Saint. She came and confessed before the people of the city that the charge she had brought against St. Eustathius the patriarch was untrue. She pointed at those who bribed her with money to lie. She indicated that the Patriarch was innocent and that the child was born to another man whose name was the same as the Patriarch. They convinced her to swear against the Saint but at the same time to mean in heart her friend who was the father of the child, to be saved from falsely swearing.", ar: "" } },
      { kind: 'reading', text: { en: "The priests resumed mentioning the name of St. Eustathius in the divine liturgy after his innocence was evident. He was eulogized and praised by on the day of his commemoration.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-28",
    title: { en: "Amshir 28", ar: "28 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Theodore, the Roman.", ar: "استشهاد القديس تادرس الرومى من أسطير" } },
      { kind: 'reading', text: { en: "On this day St. Theodore (Theodoros), the Roman, was martyred. He was from the City of Astir (Peshotep) during the reign of the Emperors Maximianus and Diocletian. When they were informed that the saint did not adore their idols, they brought him and asked him to worship the idols but he refused.", ar: "في مثل هذا اليوم استشهد القديس ثاؤدورس الرومي وكان من أهل اسطير في زمان الملكين مكسيميانوس ودقلديانوس الذين لما بلغهما إن هذا القديس لا يعبد أوثانهما استحضراه وعرضا عليه عبادة الأوثان فلم يقبل . فواعده بجوائز كثيرة فلم يذعن لقولهما فعذباه بالهنبازين وبتقطيع أعضائه وحرق جسمه بالنار وضربه بالسياط وكان صابرا علي هذا جميعه حبا في السيد المسيح الذي كان يرسل ملائكته فيعزونه ويقوونه وأخيرا قطعت رأسه ونال إكليل الشهادة . صلاته تكون معنا ولربنا المجد دائما ابديا امين ." } },
      { kind: 'reading', text: { en: "They promised him precious gifts but he did not hearken to them. They tortured him by pressing his body in the Hinbazeen, and hacking parts of his body. He was burned with fire and beat him with whips. He endured all that because of his love for the Lord Christ Who sent His angels to comfort and strengthen him. Finally he was beheaded and received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "تذكار ابادير وإيرينى" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار استشهاد القديس تذكار أبادير وإيرينى. . صلاتهما تكون معنا و لربنا المجد دائما ابديا امين ." } }
    ],
  },
  {
    id: "synax-amshir-29",
    title: { en: "Amshir 29", ar: "29 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Polycarp, Bishop of Smyrna.", ar: "استشهاد القديس بوليكاربوس أسقف سميرنا وتلميذ يوحنا البشير" } },
      { kind: 'reading', text: { en: "On this day of the year 167 A.D., St. Polycarp, Bishop of Smyrna(1), was martyred. His life began at the end of the first Christian century, and he became the disciple of . He was the one about whom the Lord said, \"And to the angel of the church in Smyrna write, 'These things says the First and the Last, Who was dead, and came to life: I know your works, tribulations and poverty, but you are rich; and I know the blasphemy of those who say they are Jews and are not, but are a synagogue of Satan. Do not fear any of those things which you are about to suffer. Indeed, the devil is about to throw some of you into prison, that you may be tested, and you will have tribulation ten days. Be faithful until death, and I will give you the crown of life.'\" (Revelation 2:8-10)", ar: "في مثل هذا اليوم من سنة 167 م استشهد القديس بوليكاربوس أسقف سميرنا الشهيرة بازمير . بدا حياته في أواخر الجيل الاول المسيحي وتتلمذ للقديس يوحنا الإنجيلي . وهو الذي يعنيه الرب بقوله &quot; اكتب إلى ملاك كنيسة سميرنا . هذا يقوله الاول والأخر . . . انا اعرف أعمالك وضيقتك وفقرك مع انك غني ، وتجديف القائلين انهم يهود وليسوا يهودا بل هم مجمع الشيطان . لا تخف البتة ممن أنت عتيد إن تتألم به . هوذا إبليس مزمع إن يلقي بعضا منكم في السجن لكي تجربوا ويكون لكم ضيق عشرة ايام . كن أمينا إلى الموت فسأعطيك إكليل الحياة &quot; . وقد سافر القديس إلى رومية سنة 157 م لإقناع انيكسيتوس أسقف رومية بشان عيد الفصح ثم عاد وباشر أعماله الرعوية وأقام علي كرسي الرعاية زمانا كبيرا حتى شاخ. ووضع مقالات كثيرة وميامر عديدة عن الميلاد المقدس والموت والجحيم والعذاب ، وعن العذراء القديسة مريم وعن تدبيرات المخلص وغير ذلك وجذب إلى الرب نفوسا كثيرة بتعاليمه المحيية." } },
      { kind: 'reading', text: { en: "St. Polycarp went to Rome in the year 157 A.D. to settle a dispute with Arikestus, Bishop of Rome, in regard to the Easter feast. He shepherded his flock well and remained on his chair for a long time until a good old age. He wrote many articles and discourses about the Holy Advent, death, hell, torments of hell, the Virgin St. Mary and many others. He attracted many souls to the Lord with his life-giving teaching.", ar: "و لما أثار مرقس اوريليوس الاضطهاد علي المسيحيين ضيقوا الخناق علي القديس قائلين احلف فنطلق سراحك . اشتم المسيح . فأجاب بوليكاربوس قائلا ستة وثمانين سنة خدمته ولم يفعل لي ضررا فكيف أجدف علي ملكي الذي خلصني ؟ ثم قال له الوالي إن كنت تستخف بالوحوش فسأجعل النيران تلتهمك ، إلا إذا تبت . فقال القديس بوليكاربوس انك تهددني بالنار التي تشتعل ساعة وبعد قليل تنطفئ لأنك لا تعرف نار الدينونة العتيدة والقصاص الأبدي المحفوظ للأشرار ولكن لماذا تتباطأ افعل ما بدا لك. وبعد اضطهادات مريرة وتهديدات عديدة أراد هذا القديس إن يسفك دمه علي اسم المسيح فأوصي شعبه وعلمهم إن يثبتوا في الإيمان وعرفهم انهم سوف لا يرون وجهه بعد ذلك اليوم . فبكوا وتعلقوا به محاولين منعه ولكنهم لم يتمكنوا من ذلك . أما هو فذهب واعترف بالرب يسوع وبعد عذابات كثيرة نالها أمر الوالي بقطع رأسه فنال إكليل الحياة . واخذ بعض المؤمنين جسده وكفنوه بإكرام." } },
      { kind: 'reading', text: { en: "When Emperor Marcus Aurelius incited persecutions against Christians, they strongly pressured him saying, \"Swear and we will set you free; curse Christ and we will spare your life.\" Polycarp replied, \"I have served my Lord Christ for 86 years and He never harmed me so how can I blaspheme against my King Who saved me?\"", ar: "صلاته تكون معنا ولربنا المجد دائما ابديا امين." } },
      { kind: 'reading', text: { en: "The Governor said, \"If you do not fear the wild beasts, I will make the fire consume you if you do not repent.\" St. Polycarp said, \"You threatened me with fire that burns for a while, then burns out, for you do not know the everlasting fire of judgement and the eternal punishment that are awaiting the evil ones. Now why are you lingering? Do whatever you want.\"", ar: "" } },
      { kind: 'reading', text: { en: "After severe tortures and many threats, the saint wished to shed his blood for Christ's name. He commanded and taught his people to be steadfast in faith and told them that they would not see his face after that day. They wept and tried to hold him down to prevent him from leaving but they failed to stop him.", ar: "" } },
      { kind: 'reading', text: { en: "He went and confessed the Lord Christ before the Governor who ordered to cut off his head after much torture; thus he received the crown of life. Some of the believers took his body, shrouded and buried it with great honor.", ar: "" } },
      { kind: 'reading', text: { en: "His prayers be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-amshir-30",
    title: { en: "Amshir 30", ar: "30 أمشير" },
    blocks: [
      { kind: 'heading', text: { en: "Abba Kyrillos the Sixth, the 116th Pope of Alexandria.", ar: "نياحة البابا الانبا كيرلس السادس" } },
      { kind: 'reading', text: { en: "On this day also of the year 1971 A.D., the holy and righteous father Abba Kyrillos the Sixth, the one hundred and sixteenth Pope of Alexandria, departed. God has accorded this pure father the gift of working great miracles even after his departure.", ar: "في هذا اليوم تذكار نياحة البابا الانبا كيرلس السادس . صلاته تكون معنا ولربنا المجد دائما ابديا امين ." } },
      { kind: 'reading', text: { en: "His prayers and blessings be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Appearance of the Head of St. John the Baptist.", ar: "وجود رأس القديس يوحنا المعمدان" } },
      { kind: 'reading', text: { en: "On this day we celebrate the commemoration of the appearance of the head of . Herod commanded his head to be cut off and brought on a platter and given to Herodias, according to her request. (Mark 6:7-28) It was said that after the feast he regretted the slaying of St. John so he kept the head in his house.", ar: "في هذا اليوم نعيد بتذكار وجود راس القديس يوحنا المعمدان . وذلك انه لما أمر هيرودس بقطع رأسه وإحضاره إليه وتقديمه إلى الفتاة هيورديا علي طبق كما طلبت قيل انه بعد انتهاء الوليمة ندم علي قتله يوحنا فابقي الرأس في منزله واتفق إن اريتاس ملك العرب صهر هيرودس ،حنق عليه لأنه طرد ابنته وتزوج بامرأة أخيه وهو حي ، فأثار عليه حربا ليثار لابنته فغلب هيرودس وشتت شمل جنوده وخرب بلاد الجليل . وقد علم طيباروس قيصر إن السبب في هذه الحروب هو قتل هيرودس لنبي عظيم في شعبه وطرده ابنة اريتاس العربي وتزوجه من امرأة أخيه . فاستدعاه إلى رومية ومعه هيروديا . فاخفي هيرودس راس القديس يوحنا في منزله وسافر . فلما وصل إلى هناك أمر طيباروس بخلعه وتجريده من جميع أمواله ثم نفاه إلى بلاد الأندلس حيث مات هناك . وخرب منزله وصار عبرة لمن يعتبر واتفق بعد مدة من السنين إن رجلين من المؤمنين من أهل حمص قصدا بيت المقدس ليقضيا مدة الصوم الكبير هناك وأمسى عليهما الوقت بالقرب من منزل هيرودس فناما فيه ليلتهما . فظهر القديس يوحنا لأحدهما واعلمه باسمه وعرفه بموضع رأسه وأمره إن يحمله معه إلى منزله . فلما استيقظ من نومه قال ذلك لرفيقه وذهبا إلى حيث المكان الذي كان راس القديس مدفونا فيه ، وحفرا فوجدا وعاء فخاريا مختوما ولما فتحاه انتشرت منه روائح طيبة ووجدا الرأس المقدس فتباركا منه ثم أعاداه إلى الوعاء . وأخذه الرجل الذي رأي الرؤيا إلى منزله ووضعه في خزانته وأضاء أمامه قنديلا . ولما دنت وفاته اعلم أخته بذلك فاستمرت هي ايضا تنير القنديل . ولم يزل الرأس ينتقل من إنسان إلى إنسان حتى انتهي إلى رجل اريوسي ، فصار ينسب ما يصنعه الرأس من الآيات إلى بدعة اريوس ، فأرسل الله عليه من طرده من مكانه وبقي مكان الرأس مجهولا حتى زمان القديس كيرلس أسقف أورشليم حيث ظهر القديس يوحنا لأنبا مرتيانوس أسقف حمص في النوم وأرشده إلى موضع الرأس . فأخذه وكان ذلك في الثلاثين من شهر أمشير . صلاة هذا القديس تكون معنا . ولربنا المجد دائما ابديا امين ." } },
      { kind: 'reading', text: { en: "Aritas, the Arabic King, Herod's father-in-law, was enraged because Herod banished his daughter and married the wife of his brother, while his brother was still alive. Aritas instigated a war against Herod in revenge for his daughter. He overcame Herod, dispersed his army and destroyed the cities of Galilee.", ar: "" } },
      { kind: 'reading', text: { en: "When Tiberius Caesar learned that the reason for these wars was the slaying of a prophet, who was great among his people, by Herod, who banished his wife, the daughter of Aritas, the Arabian king, and married his brother's wife, he summoned Herod and Herodias to Rome. Herod hid the head of St. John in his palace and went to Rome. When he arrived there, Tiberius removed him from his position and stripped him of all his possessions and exiled him to Spain where he died. Herod's palace was ruined and became an example for those who might think of following in his footsteps.", ar: "" } },
      { kind: 'reading', text: { en: "A few years later, two believing men from Homs went to Jerusalem to spend the holy fast (Lent) there. Night fell on them while passing by the ruins of Herod's palace, so they spent the night there. St. John appeared to one of them and told him about his name and the whereabouts of his head and ordered him to take it to his house. When he woke up, the man told this to his friend and they went to the place where the head was buried. They dug and found a sealed pottery vessel.", ar: "" } },
      { kind: 'reading', text: { en: "When they opened that vessel, a sweet aroma spread out of it. They found the holy head, took its blessing and placed it back in the vessel. The man that saw the vision took it to his house. He put it in a safe place and put a candle in front of it. Before his departure, he told his sister about it and she went on doing the same thing.", ar: "" } },
      { kind: 'reading', text: { en: "The head was handed from one person to another until it came to the hand of a follower of Arius who attributed the wonders and miracles that happened through the holy head to the heresy of Arius. The Lord commanded someone to force him out of his house. The place of the head remained unknown until the time of St. Cyril (Kyrillos), Bishop of Jerusalem. St. John appeared to Abba Martianus, Bishop of Homs, in his sleep and told him about the place of the head. He went there and found the head and that was on the thirtieth of the month of Amshir.", ar: "" } },
      { kind: 'reading', text: { en: "The prayers of this saint be with us and Glory be to our God forever. Amen.", ar: "" } }
    ],
  }
];
